import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
    Accordion,
    AccordionDetails,
    AccordionSummary,
    Alert,
    Box,
    Button,
    Chip,
    MenuItem,
    Paper,
    Skeleton,
    Stack,
    TextField,
    Typography,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import {
    REVIEW_CATEGORIES,
    categoryLabel,
    formatVoucherDate,
} from './expertReviewCategories';
import { orderedReview, ExpertReviewRow } from './expertReviewDisplay';
import ExpertScope3LinkFields from './ExpertScope3LinkFields';
import ExpertPager from './ExpertPager';

interface ReviewTransaction {
    _id: string;
    date?: string;
    description?: string;
    amount?: number;
    currency?: string;
    category?: string;
    subcategory?: string;
    quantity?: number;
    unit?: string;
    vendor?: { name?: string };
    msmeId?: { _id?: string; companyName?: string } | string;
    metadata?: { extractedData?: { importBatchId?: string } };
    batchId?: string;
    carbonFootprint?: {
        co2Emissions?: number;
        quantificationMethod?: string;
        calculationRecord?: { formula?: string };
        factorLineage?: { id?: string; factor?: number; unit?: string };
    };
    recommendation?: CorrectionRecommendation | null;
}

interface CorrectionRecommendation {
    title: string;
    action: string;
    category?: string;
    unit?: string;
    quantity?: number | null;
}

interface Draft {
    category: string;
    subcategory: string;
    quantity: string;
    unit: string;
    note: string;
    scope3Category: string;
}

type ClassificationPageSize = 25 | 50 | 100 | 200;

const classificationPageSize = (value: string): ClassificationPageSize => {
    if (value === '200') return 200;
    if (value === '100') return 100;
    if (value === '50') return 50;
    return 25;
};

const companyName = (row: ReviewTransaction) => {
    if (row.msmeId && typeof row.msmeId === 'object') return row.msmeId.companyName || '';
    return '';
};

const companyIdOf = (row: ReviewTransaction) => {
    if (!row.msmeId) return '';
    if (typeof row.msmeId === 'object') return String(row.msmeId._id || '');
    return String(row.msmeId);
};

const batchIdOf = (row: ReviewTransaction) => (
    row.batchId || row.metadata?.extractedData?.importBatchId || ''
);

const emptyDraft = (row: ReviewTransaction): Draft => {
    const suggested = row.recommendation;
    return {
        category: suggested?.category || row.category || 'other',
        subcategory: row.subcategory || '',
        quantity: suggested
            ? (suggested.quantity != null ? String(suggested.quantity) : '')
            : (row.quantity != null ? String(row.quantity) : ''),
        unit: suggested ? (suggested.unit || '') : (row.unit || ''),
        note: '',
        scope3Category: '',
    };
};

const quantityValue = (value: string) => {
    const parsed = Number(value);
    return value.trim() !== '' && Number.isFinite(parsed) && parsed > 0 ? parsed : null;
};

const factorLine = (row: ReviewTransaction) => {
    const factorId = row.carbonFootprint?.factorLineage?.id;
    if (!factorId || factorId === 'spend_generic' || factorId === 'activity_classification_required') {
        return 'No activity factor. Inventory 0 kg CO2e. The 0.001 kg CO2e per INR residual is not applied.';
    }
    const factor = row.carbonFootprint?.factorLineage?.factor;
    const unit = row.carbonFootprint?.factorLineage?.unit || '';
    return `Current factor ${factorId}${factor != null ? ` · ${factor} ${unit}` : ''} · ${Number(row.carbonFootprint?.co2Emissions || 0)} kg CO2e`;
};

const ExpertEmissionReview: React.FC<{
    onOpenFactorException?: (target: { msmeId: string; transactionId: string }) => void;
}> = ({ onOpenFactorException }) => {
    const [rows, setRows] = useState<ReviewTransaction[]>([]);
    const [drafts, setDrafts] = useState<Record<string, Draft>>({});
    const [page, setPage] = useState(1);
    const [pageSize, setPageSize] = useState<ClassificationPageSize>(50);
    const [pageCount, setPageCount] = useState(1);
    const [total, setTotal] = useState<number | null>(null);
    const [query, setQuery] = useState('');
    const [appliedQuery, setAppliedQuery] = useState('');
    const [activeId, setActiveId] = useState<string | null>(null);
    const [rowError, setRowError] = useState<{ id: string; message: string } | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [notice, setNotice] = useState<string | null>(null);
    const [noticeSeverity, setNoticeSeverity] = useState<'success' | 'warning'>('success');
    const [exceptionTarget, setExceptionTarget] = useState<{ msmeId: string; transactionId: string } | null>(null);
    const [savingId, setSavingId] = useState<string | null>(null);
    const plan = useMemo(() => orderedReview(rows.map((row) => ({
        _id: row._id,
        description: row.description,
        amount: row.amount,
        category: row.category,
        subcategory: row.subcategory,
        quantity: row.quantity,
        unit: row.unit,
        formula: row.carbonFootprint?.calculationRecord?.formula,
        co2Emissions: row.carbonFootprint?.co2Emissions,
        quantificationMethod: row.carbonFootprint?.quantificationMethod,
        factorId: row.carbonFootprint?.factorLineage?.id,
        recommendation: row.recommendation,
    } as ExpertReviewRow))), [rows]);
    const rowById = useMemo(() => new Map(rows.map((row) => [row._id, row])), [rows]);

    const load = useCallback(async (pageNumber: number, size: number, search: string) => {
        setLoading(true);
        setError(null);
        try {
            const response = await axios.get(buildApiUrl('/expert/emission-review'), {
                headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
                params: { limit: size, page: pageNumber, q: search || undefined },
            });
            const transactions: ReviewTransaction[] = response.data?.data?.transactions || [];
            const pagination = response.data?.data?.pagination;
            const reportedTotal = Number(pagination?.total);
            const reportedPages = Number(pagination?.pages);
            setRows(transactions);
            setTotal(Number.isFinite(reportedTotal) ? reportedTotal : null);
            setPageCount(Number.isFinite(reportedPages) && reportedPages > 0 ? reportedPages : 1);
            setDrafts(() => {
                const next: Record<string, Draft> = {};
                transactions.forEach((row) => {
                    next[row._id] = emptyDraft(row);
                });
                return next;
            });
            setActiveId((current) => (current && transactions.some((row) => row._id === current) ? current : null));
        } catch (loadError: any) {
            setError(loadError?.response?.data?.message || 'Failed to load transactions that need an activity classification.');
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        void load(page, pageSize, appliedQuery);
    }, [load, page, pageSize, appliedQuery]);

    const updateDraft = (id: string, patch: Partial<Draft>) => {
        setDrafts((current) => ({
            ...current,
            [id]: { ...(current[id] || emptyDraft({ _id: id })), ...patch },
        }));
    };

    const save = async (row: ReviewTransaction) => {
        const draft = drafts[row._id] || emptyDraft(row);
        const quantity = quantityValue(draft.quantity);
        if (quantity == null || !draft.unit.trim()) {
            setRowError({ id: row._id, message: 'Enter a quantity greater than 0 and a unit.' });
            return;
        }
        setSavingId(row._id);
        setError(null);
        setRowError(null);
        setNotice(null);
        setExceptionTarget(null);
        try {
            const response = await axios.post(
                buildApiUrl(`/expert/transactions/${row._id}/emission-review`),
                {
                    msmeId: companyIdOf(row),
                    batchId: batchIdOf(row) || undefined,
                    category: draft.category,
                    subcategory: draft.subcategory,
                    quantity,
                    unit: draft.unit,
                    note: draft.note,
                    ...(draft.scope3Category ? { scope3Category: Number(draft.scope3Category) } : {}),
                },
                { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } }
            );
            const saved = response.data?.data;
            const base = `Calculated and confirmed ${row.description || 'the voucher'} in ${categoryLabel(draft.category)}. `
                + `Factor ${saved?.factorId || 'applied'}. ${Number(saved?.co2Emissions || 0)} kg CO2e.`;
            const blocking = saved?.factorException;
            const companyId = companyIdOf(row);
            if (blocking?.blocksReport) {
                setNoticeSeverity('warning');
                setNotice(
                    `${base} Activity classification was saved. This transaction now has an open factor exception`
                    + ` (${blocking.exceptionType || 'blocking'}) that must be resolved in Factor Exceptions before an official or audit report can be generated.`
                );
                if (companyId) setExceptionTarget({ msmeId: companyId, transactionId: row._id });
            } else {
                setNoticeSeverity('success');
                setNotice(base);
            }
            setActiveId(null);
            setRows((current) => current.filter((item) => item._id !== row._id));
            setTotal((current) => (current == null ? current : Math.max(0, current - 1)));
            setPageCount((current) => {
                const nextTotal = total == null ? null : Math.max(0, total - 1);
                if (nextTotal == null) return current;
                return Math.max(1, Math.ceil(nextTotal / pageSize));
            });
        } catch (saveError: any) {
            const payload = saveError?.response?.data;
            const detail = payload?.data;
            setRowError({
                id: row._id,
                message: [
                    payload?.message,
                    detail?.code ? `Reason ${detail.code}.` : '',
                    detail?.factorId ? `Factor ${detail.factorId}.` : '',
                    detail?.nextStep || '',
                ].filter(Boolean).join(' ') || 'The classification could not be saved.',
            });
        } finally {
            setSavingId(null);
        }
    };

    const rangeStart = total != null && total > 0 && rows.length > 0 ? ((page - 1) * pageSize) + 1 : 0;
    const rangeEnd = rangeStart > 0 ? Math.min(total || 0, rangeStart + rows.length - 1) : 0;

    return (
        <Paper sx={{ p: 2, mb: 3 }}>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
              This list is the emission-review queue: an activity-factor hold, an admin emission review, or a spend-amount times emission-factor formula. The membership query is unchanged. A classification is saved only after the inventory can calculate it. A held result stays unapproved.
            </Typography>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }} sx={{ mb: 1 }}>
                <TextField
                    size="small"
                    label="Company or description"
                    value={query}
                    onChange={(event) => setQuery(event.target.value)}
                    onKeyDown={(event) => {
                        if (event.key === 'Enter') {
                            setPage(1);
                            setAppliedQuery(query.trim());
                        }
                    }}
                    sx={{ flex: '1 1 220px', maxWidth: 420 }}
                />
                <Button size="small" variant="outlined" onClick={() => { setPage(1); setAppliedQuery(query.trim()); }}>
                    Search
                </Button>
                <TextField
                    select
                    size="small"
                    label="Rows per page"
                    value={String(pageSize)}
                    onChange={(event) => { setPageSize(classificationPageSize(event.target.value)); setPage(1); }}
                    sx={{ width: 140 }}
                >
                    <MenuItem value="25">25</MenuItem>
                    <MenuItem value="50">50</MenuItem>
                    <MenuItem value="100">100</MenuItem>
                    <MenuItem value="200">200</MenuItem>
                </TextField>
            </Stack>
            {!loading || rows.length > 0 || total != null ? (
                <Typography variant="body2" sx={{ mb: 1 }}>
                    {total == null
                        ? `Loaded ${rows.length}.`
                        : (rows.length === 0
                            ? `Showing 0 of ${total}.`
                            : `Showing ${rangeStart}–${rangeEnd} of ${total}.`)}
                </Typography>
            ) : null}
            {error ? (
                <Alert
                    severity="error"
                    sx={{ mb: 2 }}
                    action={<Button color="inherit" size="small" onClick={() => void load(page, pageSize, appliedQuery)}>Retry</Button>}
                >
                    {error}
                </Alert>
            ) : null}
            {notice ? (
                <Alert
                    severity={noticeSeverity}
                    sx={{ mb: 2 }}
                    onClose={() => { setNotice(null); setExceptionTarget(null); }}
                    action={exceptionTarget ? (
                        <Button color="inherit" size="small" onClick={() => onOpenFactorException?.(exceptionTarget)}>
                            Open factor exception
                        </Button>
                    ) : null}
                >
                    {notice}
                </Alert>
            ) : null}
            {loading && rows.length === 0 ? (
                <Stack spacing={1} sx={{ mb: 2 }} aria-label="Loading transactions">
                    {[0, 1, 2].map((key) => <Skeleton key={key} variant="rounded" height={64} />)}
                </Stack>
            ) : null}
            {!loading && rows.length === 0 ? (
                <Typography variant="body2">No transactions match the emission-review queue.</Typography>
            ) : null}
            {plan.stages.length > 0 ? (
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
                    {plan.stages.map((stage) => (
                        <Chip key={stage.id} label={`${stage.title} · ${stage.open}`} color="secondary" variant="outlined" />
                    ))}
                </Box>
            ) : null}
            {plan.stages.map((stage) => (
                <Accordion key={stage.id} defaultExpanded disableGutters sx={{ overflow: 'visible', '&:before': { display: 'none' } }}>
                    <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                            <Typography sx={{ fontWeight: 700 }}>{stage.title}</Typography>
                            <Chip size="small" label={`${stage.open} to review`} />
                        </Box>
                    </AccordionSummary>
                    <AccordionDetails sx={{ overflow: 'visible', px: { xs: 1, sm: 2 } }}>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>{stage.instruction}</Typography>
                        {stage.transactionIds.map((id) => {
                            const row = rowById.get(id);
                            if (!row) return null;
                            const draft = drafts[row._id] || emptyDraft(row);
                            const when = formatVoucherDate(row.date);
                            const open = activeId === row._id;
                            const quantity = quantityValue(draft.quantity);
                            const batch = batchIdOf(row);
                            return (
                                <Box key={row._id} sx={{ borderTop: 1, borderColor: 'divider', py: 1.5 }}>
                                    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} justifyContent="space-between" alignItems={{ sm: 'center' }}>
                                        <Box sx={{ minWidth: 0 }}>
                                            <Typography variant="subtitle2" sx={{ overflowWrap: 'anywhere' }}>
                                                {row.description || 'Untitled voucher'}
                                            </Typography>
                                            <Typography variant="body2" color="text.secondary">
                                                {companyName(row) || 'Company name unavailable'}
                                                {batch ? ` · Batch ${batch}` : ''}
                                            </Typography>
                                            <Typography variant="caption" color="text.secondary" display="block">
                                                {[
                                                    when,
                                                    row.vendor?.name,
                                                    row.amount != null ? `${row.amount} ${row.currency || 'INR'}` : 'No amount',
                                                    `Category ${categoryLabel(row.category)}`,
                                                ].filter(Boolean).join(' · ')}
                                            </Typography>
                                        </Box>
                                        <Button
                                            size="small"
                                            variant={open ? 'outlined' : 'contained'}
                                            aria-label={`${open ? 'Close' : 'Classify'} ${row.description || 'this voucher'}`}
                                            onClick={() => {
                                                setActiveId(open ? null : row._id);
                                                setRowError(null);
                                            }}
                                            sx={{ textTransform: 'none', flexShrink: 0 }}
                                        >
                                            {open ? 'Close' : 'Classify'}
                                        </Button>
                                    </Stack>
                                    {open ? (
                                        <Box sx={{ mt: 1.5 }}>
                                            <Typography variant="body2" sx={{ mb: 1 }}>{factorLine(row)}</Typography>
                                            {row.recommendation ? (
                                                <Alert severity="info" sx={{ mb: 1 }}>
                                                    <Typography variant="subtitle2">{row.recommendation.title}</Typography>
                                                    <Typography variant="body2">{row.recommendation.action}</Typography>
                                                </Alert>
                                            ) : null}
                                            {rowError?.id === row._id ? (
                                                <Alert severity="error" sx={{ mb: 1 }}>{rowError.message}</Alert>
                                            ) : null}
                                            <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr', lg: 'repeat(3, minmax(0, 1fr))' }, gap: 1, alignItems: 'start', minWidth: 0 }}>
                                                <TextField
                                                    select
                                                    size="small"
                                                    label="Category"
                                                    value={REVIEW_CATEGORIES.includes(draft.category as typeof REVIEW_CATEGORIES[number]) ? draft.category : 'other'}
                                                    onChange={(event) => updateDraft(row._id, { category: event.target.value })}
                                                >
                                                    {REVIEW_CATEGORIES.map((category) => (
                                                        <MenuItem key={category} value={category}>{categoryLabel(category)}</MenuItem>
                                                    ))}
                                                </TextField>
                                                <TextField
                                                    size="small"
                                                    label="Subcategory"
                                                    value={draft.subcategory}
                                                    onChange={(event) => updateDraft(row._id, { subcategory: event.target.value })}
                                                />
                                                <TextField
                                                    size="small"
                                                    label="Quantity"
                                                    value={draft.quantity}
                                                    onChange={(event) => updateDraft(row._id, { quantity: event.target.value })}
                                                    error={draft.quantity.trim() !== '' && quantity == null}
                                                    helperText={draft.quantity.trim() !== '' && quantity == null ? 'Enter a quantity greater than 0.' : ' '}
                                                    inputProps={{ inputMode: 'decimal' }}
                                                />
                                                <TextField
                                                    size="small"
                                                    label="Unit"
                                                    value={draft.unit}
                                                    placeholder="kg, L, kWh"
                                                    onChange={(event) => updateDraft(row._id, { unit: event.target.value })}
                                                />
                                                <TextField
                                                    size="small"
                                                    label="What this purchase is"
                                                    value={draft.note}
                                                    onChange={(event) => updateDraft(row._id, { note: event.target.value })}
                                                />
                                                <Button
                                                    variant="contained"
                                                    disabled={savingId === row._id || quantity == null || !draft.unit.trim()}
                                                    onClick={() => save(row)}
                                                >
                                                    {savingId === row._id ? 'Saving' : 'Calculate and confirm'}
                                                </Button>
                                            </Box>
                                            <Box sx={{ mt: 1 }}>
                                                <ExpertScope3LinkFields
                                                    value={draft.scope3Category}
                                                    onChange={(next) => updateDraft(row._id, { scope3Category: next })}
                                                />
                                            </Box>
                                        </Box>
                                    ) : null}
                                </Box>
                            );
                        })}
                    </AccordionDetails>
                </Accordion>
            ))}
            <Box sx={{ mt: 2 }}>
                <ExpertPager page={page} pageCount={pageCount} disabled={loading} onPage={setPage} />
            </Box>
        </Paper>
    );
};

export default ExpertEmissionReview;
