import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Skeleton,
  Stack,
  Tab,
  Tabs,
  Typography,
  useTheme,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import ExpertCalculationReview from './ExpertCalculationReview';
import ExpertSubmissionQueue from './ExpertSubmissionQueue';

interface RegisteredProduct {
  productName: string;
  functionalUnit: string;
}

interface ManufacturingUnit {
  name: string;
  products: string[];
}

interface CompanyProfile {
  msmeId: string;
  companyName: string;
  industry: string;
  consultantReviewScope: string;
  registeredProductCount: number;
  registeredProducts: RegisteredProduct[];
  manufacturingUnits: ManufacturingUnit[];
  calculations: { totalsScope?: string; openRequired?: number | null };
  submissions: { totalsScope?: string; total?: number; notApproved?: number };
  factorExceptions?: { totalsScope?: string; blocking?: number | null };
}

const MOTION = '@media (prefers-reduced-motion: reduce)';

const initials = (name: string) => {
  const parts = name.split(/\s+/).filter(Boolean).slice(0, 2);
  const mark = parts.map((part) => part[0]?.toUpperCase() || '').join('');
  return mark;
};

const metricValue = (block: { totalsScope?: string; [key: string]: unknown } | undefined, field: string) => {
  if (!block || block.totalsScope !== 'complete' || typeof block[field] !== 'number' || !Number.isFinite(block[field] as number)) {
    return null;
  }
  return block[field] as number;
};

const ExpertCompanyWorkspace: React.FC<{
  msmeId: string;
  userId?: string;
  onOpenCalculations: () => void;
  onOpenTransaction?: (transactionId: string, batchId?: string) => void;
  onOpenSubmission?: (row: { msmeId: string; batchId: string }) => void;
  onBack: () => void;
  batchId?: string;
}> = ({ msmeId, userId = '', batchId = '', onOpenCalculations, onOpenTransaction, onOpenSubmission, onBack }) => {
  const theme = useTheme();
  const dark = theme.palette.mode === 'dark';
  const text = dark ? '#f1f5f9' : '#0f172a';
  const muted = dark ? '#94a3b8' : '#64748b';
  const cardBg = dark ? theme.palette.background.paper : '#ffffff';
  const border = dark ? 'rgba(241,245,249,0.12)' : 'rgba(15,23,42,0.08)';
  const pageBg = dark ? 'transparent' : '#F8FAFC';
  const [tab, setTab] = useState('summary');
  const [profile, setProfile] = useState<CompanyProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [events, setEvents] = useState<Array<{ family: string; type: string; label: string; at: string; transactionId: string; note?: string }>>([]);
  const [eventsCursor, setEventsCursor] = useState<string | null>(null);
  const [eventsError, setEventsError] = useState<string | null>(null);
  const [eventsLoading, setEventsLoading] = useState(false);

  const surface = {
    bgcolor: cardBg,
    border: `1px solid ${border}`,
    borderRadius: 2,
    minWidth: 0,
  };
  const focusRing = {
    '&:focus-visible': { outline: '2px solid #2e7d32', outlineOffset: 2 },
  };
  const enter = {
    '@keyframes workspaceIn': {
      from: { opacity: 0, transform: 'translateY(6px)' },
      to: { opacity: 1, transform: 'none' },
    },
    animation: 'workspaceIn 200ms ease both',
    [MOTION]: { animation: 'none' },
  };

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl(`/expert/companies/${msmeId}`), {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
      });
      setProfile(response.data?.data || null);
    } catch (loadError: any) {
      setProfile(null);
      setError(loadError?.response?.data?.message || 'This company could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, [msmeId]);

  useEffect(() => {
    setTab('summary');
    void load();
  }, [load]);

  const loadEvents = useCallback(async (cursor?: string | null) => {
    setEventsLoading(true);
    setEventsError(null);
    try {
      const response = await axios.get(buildApiUrl(`/expert/companies/${msmeId}/activity`), {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        params: cursor ? { cursor } : undefined,
      });
      const next = response.data?.data?.events || [];
      setEvents((current) => (cursor ? [...current, ...next] : next));
      setEventsCursor(response.data?.data?.nextCursor || null);
    } catch (loadError: any) {
      if (!cursor) setEvents([]);
      setEventsError(loadError?.response?.data?.message || 'Decision history could not be loaded.');
    } finally {
      setEventsLoading(false);
    }
  }, [msmeId]);

  useEffect(() => {
    if (tab === 'decisions') void loadEvents();
  }, [tab, loadEvents]);

  const mark = profile ? initials(profile.companyName) : '';
  const productCount = profile && typeof profile.registeredProductCount === 'number' && Number.isFinite(profile.registeredProductCount)
    ? String(profile.registeredProductCount)
    : 'Unavailable';
  const submissionsNotApproved = metricValue(profile?.submissions, 'notApproved');
  const openCalculations = metricValue(profile?.calculations, 'openRequired');

  const metric = (label: string, value: number | null) => (
    <Box sx={{ ...surface, p: 1.5, minWidth: 0, flex: '1 1 180px' }}>
      <Typography variant="caption" sx={{ color: muted }}>{label}</Typography>
      <Typography sx={{ fontWeight: 650, fontSize: '1.5rem', lineHeight: 1.2, color: value == null ? muted : text, fontVariantNumeric: 'tabular-nums' }}>
        {value == null ? 'Unavailable' : value}
      </Typography>
      {value == null ? (
        <Typography variant="caption" sx={{ color: muted }}>Complete count was not returned.</Typography>
      ) : null}
    </Box>
  );

  return (
    <Stack spacing={2} sx={{ bgcolor: pageBg, borderRadius: 2, ...enter }}>
      <Button onClick={onBack} sx={{ ...focusRing, alignSelf: 'flex-start', textTransform: 'none', minHeight: 40 }} size="small">
        Back to companies
      </Button>
      {loading && !profile ? (
        <Stack spacing={1} aria-label="Loading company">
          <Skeleton variant="rounded" height={88} sx={{ borderRadius: 2 }} />
          <Skeleton variant="rounded" height={40} sx={{ borderRadius: 2 }} />
          <Skeleton variant="rounded" height={120} sx={{ borderRadius: 2 }} />
        </Stack>
      ) : null}
      {error ? (
        <Alert severity="error" action={<Button color="inherit" size="small" onClick={() => void load()} sx={focusRing}>Retry</Button>}>{error}</Alert>
      ) : null}
      {!loading && !error && !profile ? <Typography variant="body2">This company was not found.</Typography> : null}
      {profile ? (
        <>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} alignItems={{ xs: 'flex-start', sm: 'center' }} sx={{ ...surface, p: { xs: 1.5, md: 2 } }}>
            {mark ? (
              <Box aria-hidden sx={{ width: 44, height: 44, borderRadius: '50%', bgcolor: 'rgba(76,175,80,0.16)', color: '#2e7d32', display: 'grid', placeItems: 'center', fontWeight: 700, flexShrink: 0 }}>
                {mark}
              </Box>
            ) : null}
            <Box sx={{ minWidth: 0 }}>
              <Typography variant="h5" component="h2" sx={{ fontWeight: 650, letterSpacing: '-0.02em', color: text, overflowWrap: 'anywhere' }}>{profile.companyName}</Typography>
              <Typography variant="body2" sx={{ color: muted, overflowWrap: 'anywhere' }}>
                {profile.industry || 'Industry unavailable'}
                {` · Review scope ${profile.consultantReviewScope}`}
                {` · ${productCount} registered products`}
              </Typography>
            </Box>
          </Stack>
          <Tabs
            value={tab}
            onChange={(_event, value) => setTab(value)}
            variant="scrollable"
            allowScrollButtonsMobile
            sx={{
              minHeight: 40,
              '& .MuiTab-root': { ...focusRing, textTransform: 'none', minHeight: 40, fontWeight: 650 },
              '& .MuiTabs-indicator': { transition: 'left 180ms ease, width 180ms ease', backgroundColor: '#4caf50' },
              [MOTION]: { '& .MuiTabs-indicator': { transition: 'none' } },
            }}
          >
            <Tab value="summary" label="Summary" />
            <Tab value="products" label="Products" />
            <Tab value="submissions" label="Submissions" />
            <Tab value="calculations" label="Calculations" />
            <Tab value="decisions" label="Decisions" />
          </Tabs>
          {tab === 'summary' ? (
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.25} useFlexGap flexWrap="wrap" alignItems={{ sm: 'stretch' }}>
              {metric('Submissions not approved', submissionsNotApproved)}
              {metric('Open calculations', openCalculations)}
              {metric('Blocking factor exceptions', metricValue(profile.factorExceptions, 'blocking'))}
              <Button size="small" variant="contained" onClick={onOpenCalculations} sx={{ ...focusRing, alignSelf: { xs: 'flex-start', sm: 'center' }, textTransform: 'none', boxShadow: 'none', minHeight: 40 }}>
                Open calculations
              </Button>
            </Stack>
          ) : null}
          {tab === 'products' ? (
            <Stack spacing={2}>
              <Box sx={{ ...surface, p: { xs: 1.5, md: 2 } }}>
                <Typography variant="h6" component="h3" sx={{ color: text, fontWeight: 650 }}>Registered products</Typography>
                <Typography variant="caption" sx={{ color: muted }}>From the product carbon footprint list. This count is not combined with manufacturing names.</Typography>
                {profile.registeredProducts.length === 0 ? <Typography variant="body2" sx={{ mt: 1, color: text }}>No registered products are saved.</Typography> : profile.registeredProducts.map((product) => (
                  <Typography key={`${product.productName}-${product.functionalUnit}`} variant="body2" sx={{ mt: 0.75, color: text, overflowWrap: 'anywhere' }}>
                    {product.functionalUnit ? `${product.productName} · ${product.functionalUnit}` : product.productName}
                  </Typography>
                ))}
              </Box>
              <Box sx={{ ...surface, p: { xs: 1.5, md: 2 } }}>
                <Typography variant="h6" component="h3" sx={{ color: text, fontWeight: 650 }}>Manufacturing workflow</Typography>
                <Typography variant="caption" sx={{ color: muted }}>Product names stored on manufacturing workflow units.</Typography>
                {profile.manufacturingUnits.length === 0 ? <Typography variant="body2" sx={{ mt: 1, color: text }}>No manufacturing units are saved.</Typography> : profile.manufacturingUnits.map((unit) => (
                  <Box key={unit.name} sx={{ mt: 1 }}>
                    <Typography variant="subtitle2" sx={{ color: text, overflowWrap: 'anywhere' }}>{unit.name}</Typography>
                    <Typography variant="body2" sx={{ color: text, overflowWrap: 'anywhere' }}>{unit.products.length ? unit.products.join(', ') : 'No product names on this unit.'}</Typography>
                  </Box>
                ))}
              </Box>
            </Stack>
          ) : null}
          {tab === 'submissions' ? (
            <ExpertSubmissionQueue
              msmeId={profile.msmeId}
              companyNames={{ [profile.msmeId]: profile.companyName }}
              onOpenBatch={onOpenSubmission}
            />
          ) : null}
          {tab === 'calculations' ? (
            <ExpertCalculationReview
              embedded
              companyId={profile.msmeId}
              batchId={batchId}
              selectedUser={userId ? { userId, name: profile.companyName, email: '', companyName: profile.companyName, msmeId: profile.msmeId } : undefined}
            />
          ) : null}
          {tab === 'decisions' ? (
            <Stack spacing={1}>
              {eventsLoading && events.length === 0 ? <Skeleton variant="rounded" height={72} sx={{ borderRadius: 2 }} /> : null}
              {eventsError ? <Alert severity="error" action={<Button color="inherit" size="small" onClick={() => void loadEvents()} sx={focusRing}>Retry</Button>}>{eventsError}</Alert> : null}
              {!eventsLoading && !eventsError && events.length === 0 ? <Typography variant="body2" role="status">No expert decisions or clarifications are recorded for this company.</Typography> : null}
              {events.map((event) => (
                <Stack key={`${event.family}-${event.transactionId}-${event.at}-${event.type}`} direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" spacing={1} sx={{ ...surface, p: 1.5 }}>
                  <Box sx={{ minWidth: 0 }}>
                    <Typography variant="body2" sx={{ fontWeight: 700, color: text }}>{`${event.family === 'clarification' ? 'Clarification' : 'Decision'} · ${event.label}`}</Typography>
                    <Typography variant="caption" sx={{ color: muted }}>{event.at ? new Date(event.at).toLocaleString() : 'Time unavailable'}</Typography>
                    {event.note ? <Typography variant="body2" sx={{ color: text, overflowWrap: 'anywhere' }}>{event.note}</Typography> : null}
                    {event.label === 'Clarification reviewed' ? <Typography variant="caption" display="block" sx={{ color: muted }}>This is a clarification event, not an approval.</Typography> : null}
                  </Box>
                  <Button size="small" onClick={() => (onOpenTransaction ? onOpenTransaction(event.transactionId) : onOpenCalculations())} sx={{ ...focusRing, alignSelf: { xs: 'flex-start', sm: 'center' }, textTransform: 'none', flexShrink: 0 }}>
                    Open calculation
                  </Button>
                </Stack>
              ))}
              {eventsCursor ? (
                <Button size="small" disabled={eventsLoading} onClick={() => void loadEvents(eventsCursor)} sx={{ ...focusRing, textTransform: 'none', alignSelf: 'flex-start' }}>
                  {eventsLoading ? 'Loading older events' : 'Load older events'}
                </Button>
              ) : null}
            </Stack>
          ) : null}
        </>
      ) : null}
    </Stack>
  );
};

export default ExpertCompanyWorkspace;
