import React, { useCallback, useEffect, useState } from 'react';
import { Alert, Box, Button, Skeleton, Stack, Table, TableBody, TableCell, TableHead, TableRow, Typography } from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

interface HoldRow {
  transactionId: string;
  msmeId: string;
  companyName?: string;
  description?: string;
  batchId?: string;
  billStatus?: string;
  informationRequest?: { status?: string; question?: string; reply?: string } | null;
}

const ExpertHoldList: React.FC<{ kind: 'clarifications' | 'bills' }> = ({ kind }) => {
  const [rows, setRows] = useState<HoldRow[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [scope, setScope] = useState<'loaded_page' | 'complete'>('complete');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async (append: boolean, nextCursor?: string | null) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl(kind === 'bills' ? '/expert/bills' : '/expert/clarifications'), {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        params: { limit: 25, cursor: nextCursor || undefined },
      });
      const page: HoldRow[] = response.data?.data?.rows || [];
      setRows((current) => {
        if (!append) return page;
        const seen = new Set(current.map((row) => row.transactionId));
        return [...current, ...page.filter((row) => !seen.has(row.transactionId))];
      });
      setCursor(response.data?.data?.nextCursor || null);
      setScope(response.data?.data?.totalsScope === 'loaded_page' ? 'loaded_page' : 'complete');
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'The list could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, [kind]);

  useEffect(() => {
    setRows([]);
    setCursor(null);
    void load(false);
  }, [load]);

  const title = kind === 'bills' ? 'Bills required' : 'Clarifications';
  const note = kind === 'bills'
    ? 'High-value vouchers still waiting for a bill. This page is not the whole ledger.'
    : 'Unanswered requests and replies that an expert has not marked reviewed. An answered reply still blocks approval.';

  return (
    <Stack spacing={2}>
      <Typography variant="h6" component="h2">{title}</Typography>
      <Typography variant="body2" color="text.secondary">{note}</Typography>
      {scope === 'loaded_page' ? <Typography variant="caption" color="text.secondary">More rows remain on the server.</Typography> : null}
      {error ? <Alert severity="error" action={<Button color="inherit" size="small" onClick={() => void load(false)}>Retry</Button>}>{error}</Alert> : null}
      {loading && rows.length === 0 ? <Skeleton variant="rounded" height={88} aria-label={`Loading ${title}`} /> : null}
      {!loading && !error && rows.length === 0 ? <Typography variant="body2">{kind === 'bills' ? 'No bills are waiting.' : 'No clarifications are waiting.'}</Typography> : null}
      {rows.length > 0 ? (
        <Box sx={{ overflowX: 'auto' }}>
          <Table size="small" aria-label={title} sx={{ minWidth: 720 }}>
            <TableHead>
              <TableRow>
                <TableCell>Company</TableCell>
                <TableCell>Transaction</TableCell>
                <TableCell>Batch</TableCell>
                <TableCell>{kind === 'bills' ? 'Bill status' : 'Request'}</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map((row) => (
                <TableRow key={row.transactionId}>
                  <TableCell>{row.companyName || 'Company name unavailable'}</TableCell>
                  <TableCell>{row.description || row.transactionId}</TableCell>
                  <TableCell>{row.batchId || 'Batch unavailable'}</TableCell>
                  <TableCell>
                    {kind === 'bills'
                      ? (row.billStatus || 'Awaiting bill')
                      : `${row.informationRequest?.status || 'open'}${row.informationRequest?.question ? ` · ${row.informationRequest.question}` : ''}`}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </Box>
      ) : null}
      {cursor ? <Button onClick={() => void load(true, cursor)} disabled={loading}>Load more</Button> : null}
    </Stack>
  );
};

export default ExpertHoldList;
