import React from 'react';
import { Button, Stack, Typography } from '@mui/material';

export const pageWindow = (page: number, pageCount: number): Array<number | 'gap'> => {
  const count = Math.max(1, pageCount);
  const current = Math.min(Math.max(1, page), count);
  if (count <= 7) {
    return Array.from({ length: count }, (_, index) => index + 1);
  }
  const wanted = new Set<number>([1, count, current - 1, current, current + 1]);
  const ordered = Array.from(wanted).filter((value) => value >= 1 && value <= count).sort((left, right) => left - right);
  const window: Array<number | 'gap'> = [];
  ordered.forEach((value, index) => {
    if (index > 0 && value - ordered[index - 1] > 1) window.push('gap');
    window.push(value);
  });
  return window;
};

const ExpertPager: React.FC<{
  page: number;
  pageCount: number;
  disabled?: boolean;
  onPage: (page: number) => void;
}> = ({ page, pageCount, disabled = false, onPage }) => {
  const count = Math.max(1, pageCount, page);
  const current = Math.min(Math.max(1, page), count);
  const items = pageWindow(current, count);
  return (
    <Stack direction="row" spacing={0.5} alignItems="center" flexWrap="wrap" useFlexGap aria-label="Page navigation">
      <Button size="small" disabled={disabled || current <= 1} onClick={() => onPage(current - 1)}>
        Previous page
      </Button>
      {items.map((item, index) => (
        item === 'gap' ? (
          <Typography key={`gap-${index}`} variant="body2" component="span" aria-hidden="true">…</Typography>
        ) : (
          <Button
            key={item}
            size="small"
            variant={item === current ? 'contained' : 'text'}
            aria-label={`Page ${item}`}
            aria-current={item === current ? 'page' : undefined}
            disabled={disabled || item === current}
            onClick={() => onPage(item)}
          >
            {item}
          </Button>
        )
      ))}
      <Button size="small" disabled={disabled || current >= count} onClick={() => onPage(current + 1)}>
        Next page
      </Button>
    </Stack>
  );
};

export default ExpertPager;
