import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Button,
  Chip,
  Drawer,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  MenuItem,
  Paper,
  Skeleton,
  Stack,
  TextField,
  ToggleButton,
  ToggleButtonGroup,
  Typography,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import { downloadUncertainWorkbook } from './downloadUncertainWorkbook';
import { categoryLabel } from './expertReviewCategories';
import ExpertReviewWizard from './ExpertReviewWizard';
import ExpertReviewTogether from './ExpertReviewTogether';
import ExpertPager from './ExpertPager';
import ExpertReviewTable from './ExpertReviewTable';
import ExpertScope3Boundary from './ExpertScope3Boundary';
import {
  ExpertReviewRow,
  ReviewPageFilter,
  canSelectForSharedAssessment,
  isRowApproved,
  lacksActivityQuantity,
  orderedReview,
  rowMatchesPageFilter,
  similarOpenRows,
} from './expertReviewDisplay';

interface CompanySummary {
  msmeId: string;
  companyName: string;
  scope: 'required' | 'all';
  openRequired: number;
  counts: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
  open: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
}

interface CorrectionAssistance {
  transactionId?: string;
  needsAssistance: boolean;
  referToRecommendation: boolean;
  message: string;
  apply?: {
    category?: string;
    quantity?: number | null;
    unit?: string;
    factorId?: string;
    factorLabel?: string;
  } | null;
}

export interface ConsultantUserSelection {
  userId: string;
  name: string;
  email: string;
  companyName: string;
  msmeId: string;
}

const approvalEffect = (name?: string) => (
  name
    ? `Analytics and report generation for ${name} now use this calculation.`
    : 'Analytics and report generation for this user now use this calculation.'
);

interface QueueSummary {
  counts?: {
    excluded?: number;
    spendBased?: number;
    calculated?: number;
    withoutCalculation?: number;
  };
  openRequired?: number;
  totalsScope?: string;
  companyName?: string;
}

const PAGE_FILTERS: { id: ReviewPageFilter; label: string }[] = [
  { id: 'all', label: 'All' },
  { id: 'open', label: 'Open' },
  { id: 'approved', label: 'Approved' },
  { id: 'clarification', label: 'Clarification' },
  { id: 'bill', label: 'Bill required' },
  { id: 'rejected', label: 'Rejected' },
  { id: 'excluded', label: 'Excluded' },
];

const formatCount = (value: number) => value.toLocaleString('en-US');

type ReviewPageSize = 50 | 100 | 200;

const reviewPageSize = (value: string): ReviewPageSize => {
  if (value === '200') return 200;
  if (value === '100') return 100;
  return 50;
};

const ledgerTotalOf = (summary: QueueSummary | null) => {
  const counts = summary?.counts;
  if (!counts) return null;
  return Number(counts.excluded || 0)
    + Number(counts.spendBased || 0)
    + Number(counts.calculated || 0)
    + Number(counts.withoutCalculation || 0);
};

const ExpertCalculationReview: React.FC<{
  selectedUser?: ConsultantUserSelection;
  companyId?: string;
  batchId?: string;
  focusTransactionId?: string;
  onBackToDirectory?: () => void;
  onOpenCompany?: (company: CompanySummary) => void;
  onCompanyName?: (companyName: string) => void;
  chooseCompany?: boolean;
  embedded?: boolean;
}> = ({
  selectedUser,
  companyId = '',
  batchId = '',
  focusTransactionId = '',
  onBackToDirectory,
  chooseCompany = false,
  onOpenCompany,
  onCompanyName,
  embedded = false,
}) => {
  const [companies, setCompanies] = useState<CompanySummary[]>([]);
  const [companyCursor, setCompanyCursor] = useState<string | null>(null);
  const [companyQuery, setCompanyQuery] = useState('');
  const [appliedCompanyQuery, setAppliedCompanyQuery] = useState('');
  const [loadingMoreCompanies, setLoadingMoreCompanies] = useState(false);
  const [msmeId, setMsmeId] = useState(selectedUser?.msmeId || companyId || '');
  const [rows, setRows] = useState<ExpertReviewRow[]>([]);
  const [pageSize, setPageSize] = useState<ReviewPageSize>(50);
  const [page, setPage] = useState(1);
  const [queueTotal, setQueueTotal] = useState<number | null>(null);
  const [pageCount, setPageCount] = useState(1);
  const [truncated, setTruncated] = useState(false);
  const [summary, setSummary] = useState<QueueSummary | null>(null);
  const [queueSummaryScope, setQueueSummaryScope] = useState('complete');
  const [sessionApprovedIds, setSessionApprovedIds] = useState<string[]>([]);
  const [openOffset, setOpenOffset] = useState(0);
  const [pageFilter, setPageFilter] = useState<ReviewPageFilter>('all');
  const [note, setNote] = useState('');
  const [loading, setLoading] = useState(true);
  const [paging, setPaging] = useState(false);
  const [queueSettled, setQueueSettled] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [downloading, setDownloading] = useState(false);
  const [assistanceById, setAssistanceById] = useState<Record<string, CorrectionAssistance>>({});
  const [askingId, setAskingId] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [detailMounted, setDetailMounted] = useState(Boolean(focusTransactionId));
  const [detailOpen, setDetailOpen] = useState(Boolean(focusTransactionId));
  const [activeId, setActiveId] = useState<string | null>(focusTransactionId || null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const deskRef = useRef<HTMLDivElement>(null);
  const requestRef = useRef(0);
  const token = () => localStorage.getItem('token');
  const reviewContext = (row: ExpertReviewRow) => ({
    msmeId: row.msmeId || companyId || msmeId,
    batchId: row.batchId || batchId || undefined,
  });
  const openRows = rows.filter((row) => !row.settled);
  const bulkBlocked = openRows.some(lacksActivityQuantity);
  const visibleRows = rows.filter((row) => rowMatchesPageFilter(row, pageFilter));
  const pageEligible = rows.filter(canSelectForSharedAssessment);
  const eligibleRows = visibleRows.filter(canSelectForSharedAssessment);
  const selectedOnPage = selectedIds.filter((id) => rows.some((row) => row._id === id)).length;
  const selectedInFilter = selectedIds.filter((id) => visibleRows.some((row) => row._id === id)).length;
  const sessionOnThisPage = sessionApprovedIds.filter((id) => (
    rows.some((row) => row._id === id && isRowApproved(row))
  )).length;
  const sessionOnOtherPages = sessionApprovedIds.filter((id) => (
    !rows.some((row) => row._id === id)
  )).length;
  const ledgerTotal = ledgerTotalOf(summary);
  const openLedger = summary && summary.openRequired != null
    ? Math.max(0, Number(summary.openRequired) - openOffset)
    : null;
  const pageApproved = rows.filter(isRowApproved).length;
  const pageClarification = rows.filter((row) => (
    row.informationRequest?.status === 'open' || row.informationRequest?.status === 'answered'
  )).length;

  const loadCompanies = useCallback(async (cursor?: string | null, search = appliedCompanyQuery) => {
    const append = Boolean(cursor);
    if (append) setLoadingMoreCompanies(true);
    else setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/calculation-review'), {
        headers: { Authorization: `Bearer ${token()}` },
        params: { limit: 25, cursor: cursor || undefined, q: search || undefined },
      });
      const list: CompanySummary[] = response.data?.data?.companies || [];
      const next = response.data?.data?.nextCursor || null;
      setCompanyCursor(next);
      setCompanies((current) => {
        if (!append) return list;
        const seen = new Set(current.map((company) => company.msmeId));
        return [...current, ...list.filter((company) => !seen.has(company.msmeId))];
      });
      if (!append) {
        setMsmeId((current) => {
          const preferred = selectedUser?.msmeId || companyId || '';
          if (preferred) return preferred;
          if (chooseCompany) return '';
          if (current) return current;
          const withOpenWork = list.find((company) => Number(company.openRequired) > 0);
          return withOpenWork?.msmeId || '';
        });
      }
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Failed to load companies waiting for review.');
    } finally {
      if (append) setLoadingMoreCompanies(false);
      else setLoading(false);
    }
  }, [selectedUser?.msmeId, companyId, chooseCompany, appliedCompanyQuery]);

  useEffect(() => {
    const preferred = selectedUser?.msmeId || companyId || '';
    if (preferred) setMsmeId(preferred);
    else if (chooseCompany) setMsmeId('');
  }, [selectedUser?.msmeId, companyId, chooseCompany]);

  useEffect(() => {
    if (!msmeId || !onCompanyName) return;
    const name = summary?.companyName
      || companies.find((company) => company.msmeId === msmeId)?.companyName
      || selectedUser?.companyName
      || '';
    if (name) onCompanyName(name);
  }, [msmeId, summary, companies, selectedUser?.companyName, onCompanyName]);

  const loadRows = useCallback(async (company: string, pageNumber: number, size: number) => {
    if (!company) {
      setRows([]);
      setQueueTotal(null);
      setPageCount(1);
      setTruncated(false);
      setSummary(null);
      setPaging(false);
      setQueueSettled(true);
      return;
    }
    const request = requestRef.current + 1;
    requestRef.current = request;
    setPaging(true);
    try {
      const response = await axios.get(buildApiUrl('/expert/calculation-review'), {
        headers: { Authorization: `Bearer ${token()}` },
        params: {
          msmeId: company,
          limit: size,
          page: pageNumber,
          transactionId: pageNumber === 1 ? (focusTransactionId || undefined) : undefined,
          batchId: batchId || undefined,
        },
      });
      if (request !== requestRef.current) return;
      const loaded: ExpertReviewRow[] = response.data?.data?.transactions || [];
      const focused = response.data?.data?.focused as ExpertReviewRow | null;
      const withFocus = pageNumber === 1 && focused && !loaded.some((row) => row._id === focused._id)
        ? [focused, ...loaded]
        : loaded;
      const reportedTotal = Number(response.data?.data?.queueTotal);
      const reportedCount = Number(response.data?.data?.pageCount);
      setRows(orderedReview(withFocus).transactions);
      setQueueTotal(Number.isFinite(reportedTotal) ? reportedTotal : null);
      setPageCount(Number.isFinite(reportedCount) && reportedCount > 0 ? reportedCount : 1);
      setTruncated(Boolean(
        response.data?.data?.truncated
        || response.data?.data?.nextCursor
        || (Number.isFinite(reportedCount) && pageNumber < reportedCount)
      ));
      setQueueSummaryScope(response.data?.data?.summary?.totalsScope || 'complete');
      setSummary(response.data?.data?.summary || null);
      setOpenOffset(0);
      if (scrollRef.current) scrollRef.current.scrollTop = 0;
    } catch (loadError: any) {
      if (request !== requestRef.current) return;
      setError(loadError?.response?.data?.message || 'Failed to load the company review.');
    } finally {
      if (request === requestRef.current) {
        setPaging(false);
        setQueueSettled(true);
      }
    }
  }, [focusTransactionId, batchId]);

  const refreshQueueSummary = useCallback(async (company: string, pageNumber: number, size: number) => {
    if (!company) return;
    const response = await axios.get(buildApiUrl('/expert/calculation-review'), {
      headers: { Authorization: `Bearer ${token()}` },
      params: {
        msmeId: company,
        limit: size,
        page: pageNumber,
        batchId: batchId || undefined,
      },
    });
    const reportedTotal = Number(response.data?.data?.queueTotal);
    const reportedCount = Number(response.data?.data?.pageCount);
    if (Number.isFinite(reportedTotal)) setQueueTotal(reportedTotal);
    if (Number.isFinite(reportedCount) && reportedCount > 0) setPageCount(reportedCount);
    if (response.data?.data?.summary) {
      setQueueSummaryScope(response.data.data.summary.totalsScope || 'complete');
      setSummary(response.data.data.summary);
    }
    setOpenOffset(0);
  }, [batchId]);

  useEffect(() => {
    void loadCompanies();
  }, [loadCompanies]);

  const queueIdentity = `${msmeId}|${pageSize}|${batchId}|${focusTransactionId}`;
  const identityRef = useRef(queueIdentity);
  const identityChanged = identityRef.current !== queueIdentity;
  if (identityChanged) {
    identityRef.current = queueIdentity;
    if (page !== 1) setPage(1);
  }
  const pageForLoad = identityChanged ? 1 : page;
  const reviewStart = queueTotal != null && queueTotal > 0 && rows.length > 0
    ? ((pageForLoad - 1) * pageSize) + 1
    : 0;
  const reviewEnd = reviewStart > 0 ? Math.min(queueTotal || 0, reviewStart + rows.length - 1) : 0;
  const displayPageCount = truncated && pageForLoad >= pageCount ? pageForLoad + 1 : pageCount;

  useEffect(() => {
    setSelectedIds([]);
    setPageFilter('all');
    setSessionApprovedIds([]);
    setDetailMounted(Boolean(focusTransactionId));
    setDetailOpen(Boolean(focusTransactionId));
    setActiveId(focusTransactionId || null);
    setRows([]);
    setSummary(null);
    setQueueTotal(null);
    setOpenOffset(0);
    setTruncated(false);
    setQueueSettled(false);
  }, [msmeId, pageSize, focusTransactionId, batchId]);

  useEffect(() => {
    setSelectedIds([]);
    setDetailOpen((open) => (pageForLoad === 1 && focusTransactionId ? open : false));
    void loadRows(msmeId, pageForLoad, pageSize);
  }, [loadRows, msmeId, pageForLoad, pageSize, focusTransactionId]);

  const bumpApproved = (row: ExpertReviewRow) => {
    if (row.settled || row.businessStatus === 'Approved') return;
    setSessionApprovedIds((current) => (current.includes(row._id) ? current : [...current, row._id]));
    setOpenOffset((count) => count + 1);
  };

  const selectEligible = () => {
    if (pageFilter === 'all') {
      setSelectedIds(pageEligible.map((row) => row._id));
      return;
    }
    const visibleIds = new Set(visibleRows.map((row) => row._id));
    setSelectedIds((current) => [
      ...current.filter((id) => !visibleIds.has(id)),
      ...eligibleRows.map((row) => row._id),
    ]);
  };

  const openDetail = (id: string) => {
    setDetailMounted(true);
    setActiveId(id);
    setDetailOpen(true);
  };

  const showPage = (nextPage: number) => {
    setPage(nextPage);
  };

  const rejectOne = async (row: ExpertReviewRow, reason: string) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/calculation-review/reject`),
        { reason, msmeId: row.msmeId || msmeId, batchId: row.batchId || batchId || undefined },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const saved = response.data?.data;
      setNotice(`Rejected ${row.description || 'the voucher'}. ${saved?.businessStatusReason || reason}`);
      setRows((current) => current.map((item) => (
        item._id === row._id
          ? {
            ...item,
            businessStatus: saved?.businessStatus || 'Rejected',
            businessStatusReason: saved?.businessStatusReason || `Expert rejected this transaction: ${reason}`,
          }
          : item
      )));
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The rejection could not be saved.');
    } finally {
      setBusyId(null);
    }
  };

  const confirmOne = async (row: ExpertReviewRow, scope3Category?: number) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/calculation-review/confirm`),
        {
          note,
          ...reviewContext(row),
          ...(scope3Category ? { scope3Category } : {}),
          ...(row.fingerprint ? { expectedFingerprint: row.fingerprint } : {}),
        },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const kilograms = Number(row.co2Emissions || 0);
      setNotice(`Approved ${row.description || 'the voucher'} in ${categoryLabel(row.category)}. ${kilograms} kg CO2e. ${approvalEffect(selectedUser?.name)}`);
      bumpApproved(row);
      setRows((current) => current.map((item) => (
        item._id === row._id
          ? { ...item, settled: true, settledKilograms: kilograms, businessStatus: 'Approved' }
          : item
      )));
      await loadCompanies();
      try {
        await refreshQueueSummary(msmeId, pageForLoad, pageSize);
      } catch (refreshError: any) {
        setError(refreshError?.response?.data?.message || 'The queue totals could not be refreshed.');
      }
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The confirmation could not be saved.');
    } finally {
      setBusyId(null);
    }
  };

  const heldMessage = (saveError: any) => {
    const payload = saveError?.response?.data;
    const detail = payload?.data;
    return [
      payload?.message,
      detail?.code ? `Reason ${detail.code}.` : '',
      detail?.factorId ? `Factor ${detail.factorId}.` : '',
      detail?.nextStep || '',
    ].filter(Boolean).join(' ') || 'The correction could not be saved.';
  };

  const correctOne = async (row: ExpertReviewRow, draft: { category: string; subcategory?: string; quantity: string; unit: string; scope3Category?: string }) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/emission-review`),
        {
          ...reviewContext(row),
          category: draft.category,
          subcategory: draft.subcategory || row.subcategory || '',
          quantity: Number(draft.quantity),
          unit: draft.unit,
          ...(draft.scope3Category ? { scope3Category: Number(draft.scope3Category) } : {}),
          note: note || 'Corrected by the expert consultant.',
        },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const saved = response.data?.data;
      const kilograms = Number(saved?.co2Emissions || 0);
      setNotice(
        `Corrected and approved ${row.description || 'the voucher'} in ${categoryLabel(draft.category)}. `
        + `Factor ${saved?.factorId || 'applied'}. ${kilograms} kg CO2e. ${approvalEffect(selectedUser?.name)}`
      );
      bumpApproved(row);
      setRows((current) => current.map((item) => (
        item._id === row._id
          ? {
            ...item,
            settled: true,
            settledKilograms: kilograms,
            priorKilograms: Number(item.co2Emissions || 0),
            factorId: saved?.factorId || item.factorId,
            category: draft.category,
            quantity: Number(draft.quantity),
            unit: draft.unit,
            businessStatus: 'Approved',
          }
          : item
      )));
      await loadCompanies();
      try {
        await refreshQueueSummary(msmeId, pageForLoad, pageSize);
      } catch (refreshError: any) {
        setError(refreshError?.response?.data?.message || 'The queue totals could not be refreshed.');
      }
    } catch (saveError: any) {
      setError(heldMessage(saveError));
    } finally {
      setBusyId(null);
    }
  };

  const selectedRows = rows.filter((row) => selectedIds.includes(row._id) && canSelectForSharedAssessment(row));

  const correctSelected = async (draft: { category: string; quantity: string; unit: string; scope3Category?: string }) => {
    if (selectedRows.length < 2 || draft.quantity === '' || !draft.unit) return;
    setBusyId('selected');
    setError(null);
    setNotice(null);
    const done: string[] = [];
    try {
      for (const row of selectedRows) {
        const response = await axios.post(
          buildApiUrl(`/expert/transactions/${row._id}/emission-review`),
          {
            ...reviewContext(row),
            category: draft.category,
            subcategory: row.subcategory || '',
            quantity: Number(draft.quantity),
            unit: draft.unit,
            ...(draft.scope3Category ? { scope3Category: Number(draft.scope3Category) } : {}),
            note: note || 'Corrected by the expert consultant for similar transactions.',
          },
          { headers: { Authorization: `Bearer ${token()}` } },
        );
        const saved = response.data?.data;
        const kilograms = Number(saved?.co2Emissions || 0);
        done.push(row._id);
        bumpApproved(row);
        setRows((current) => current.map((item) => (
          item._id === row._id
            ? {
              ...item,
              settled: true,
              settledKilograms: kilograms,
              priorKilograms: Number(item.co2Emissions || 0),
              factorId: saved?.factorId || item.factorId,
              category: draft.category,
              quantity: Number(draft.quantity),
              unit: draft.unit,
              businessStatus: 'Approved',
            }
            : item
        )));
      }
      setNotice(
        `Corrected and approved ${done.length} transactions in ${categoryLabel(draft.category)}. ${approvalEffect(selectedUser?.name)}`
      );
      setSelectedIds([]);
      await loadCompanies();
    } catch (saveError: any) {
      setError(heldMessage(saveError) || 'The shared correction could not be saved.');
      setSelectedIds((current) => current.filter((id) => !done.includes(id)));
    } finally {
      setBusyId(null);
    }
  };

  const confirmSelected = async (scope3Category?: number) => {
    if (selectedRows.length < 2) return;
    setBusyId('selected');
    setError(null);
    setNotice(null);
    const done: string[] = [];
    try {
      for (const row of selectedRows) {
        await axios.post(
          buildApiUrl(`/expert/transactions/${row._id}/calculation-review/confirm`),
          {
            note,
            ...reviewContext(row),
            ...(scope3Category ? { scope3Category } : {}),
            ...(row.fingerprint ? { expectedFingerprint: row.fingerprint } : {}),
          },
          { headers: { Authorization: `Bearer ${token()}` } },
        );
        done.push(row._id);
        bumpApproved(row);
        setRows((current) => current.map((item) => (
          item._id === row._id
            ? { ...item, settled: true, settledKilograms: Number(item.co2Emissions || 0), businessStatus: 'Approved' }
            : item
        )));
      }
      setNotice(`Approved ${done.length} transactions. ${approvalEffect(selectedUser?.name)}`);
      setSelectedIds([]);
      await loadCompanies();
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The selected rows could not be approved.');
      setSelectedIds((current) => current.filter((id) => !done.includes(id)));
    } finally {
      setBusyId(null);
    }
  };

  const askSelected = async (request: { kind: 'details' | 'bill'; question: string }) => {
    if (selectedRows.length < 2) return;
    setBusyId('selected');
    setError(null);
    setNotice(null);
    const done: string[] = [];
    try {
      for (const row of selectedRows) {
        const response = await axios.post(
          buildApiUrl(`/expert/transactions/${row._id}/information-request`),
          { ...request, msmeId: row.msmeId || msmeId, batchId: row.batchId || batchId || undefined },
          { headers: { Authorization: `Bearer ${token()}` } },
        );
        const informationRequest = response.data?.data?.informationRequest;
        done.push(row._id);
        setRows((current) => current.map((item) => (
          item._id === row._id ? { ...item, informationRequest } : item
        )));
      }
      setNotice(request.kind === 'bill'
        ? `Asked the company for the bill on ${done.length} transactions.`
        : `Asked the company for more information on ${done.length} transactions.`);
      setSelectedIds([]);
    } catch (requestError: any) {
      setError(requestError?.response?.data?.message || 'The request could not be sent for every selected transaction.');
      setSelectedIds((current) => current.filter((id) => !done.includes(id)));
    } finally {
      setBusyId(null);
    }
  };

  const confirmOpen = async (category?: string) => {
    if (!msmeId) return;
    const prompt = category
      ? `Approve eligible ${category} rows for this company?`
      : 'Approve all eligible legacy rows for this company? Rows in an Expert Approval submission are not included.';
    if (!window.confirm(prompt)) return;
    setBusyId(category || 'all');
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl('/expert/calculation-review/confirm-open'),
        { msmeId, note, category: category || undefined, confirmScope: 'company' },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      setNotice(response.data?.message || 'Open rows confirmed.');
      await loadCompanies();
      setPage(1);
      await loadRows(msmeId, 1, pageSize);
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The open rows could not be confirmed.');
    } finally {
      setBusyId(null);
    }
  };

  const askCompany = async (row: ExpertReviewRow, request: { kind: 'details' | 'bill'; question: string }) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/information-request`),
        { ...request, msmeId: row.msmeId || msmeId, batchId: row.batchId || batchId || undefined },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const informationRequest = response.data?.data?.informationRequest;
      setNotice(response.data?.message || 'Asked the company for more information.');
      setRows((current) => current.map((item) => (
        item._id === row._id ? { ...item, informationRequest } : item
      )));
    } catch (requestError: any) {
      setError(requestError?.response?.data?.message || 'The request could not be sent.');
    } finally {
      setBusyId(null);
    }
  };

  const reviewReply = async (row: ExpertReviewRow) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/information-request/review`),
        { msmeId: row.msmeId || msmeId, batchId: row.batchId || batchId || undefined },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      setRows((current) => current.map((item) => (
        item._id === row._id ? { ...item, informationRequest: null } : item
      )));
      setNotice('The company reply was marked reviewed. It is not an approval.');
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The reply could not be marked reviewed.');
    } finally {
      setBusyId(null);
    }
  };

  const cancelRequest = async (row: ExpertReviewRow) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/information-request/cancel`),
        { msmeId: row.msmeId || msmeId, batchId: row.batchId || batchId || undefined },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      setNotice('The request was cancelled. You can correct this row.');
      setRows((current) => current.map((item) => (
        item._id === row._id ? { ...item, informationRequest: null } : item
      )));
    } catch (requestError: any) {
      setError(requestError?.response?.data?.message || 'The request could not be cancelled.');
    } finally {
      setBusyId(null);
    }
  };

  const askAgent = async (row: ExpertReviewRow) => {
    setAskingId(row._id);
    setError(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/correction-assistance`),
        reviewContext(row),
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const assistance = response.data?.data?.assistance?.[0];
      if (!assistance) {
        setError('The correction agent did not return a recommendation.');
        return;
      }
      setAssistanceById((current) => ({ ...current, [row._id]: assistance }));
    } catch (assistError: any) {
      setError(assistError?.response?.data?.message || 'The correction agent could not be reached.');
    } finally {
      setAskingId(null);
    }
  };

  const downloadRows = async () => {
    if (!msmeId) return;
    setDownloading(true);
    setError(null);
    try {
      await downloadUncertainWorkbook(msmeId);
    } catch (downloadError: any) {
      setError(downloadError?.response?.data?.message || 'The uncertain transactions workbook could not be downloaded.');
    } finally {
      setDownloading(false);
    }
  };

  const selected = companies.find((company) => company.msmeId === msmeId);
  const theme = useTheme();
  const desk = useMediaQuery(theme.breakpoints.up('lg'));
  const deskLocked = Boolean(detailOpen && desk);
  const awaitingQueue = Boolean(msmeId) && !queueSettled;
  useEffect(() => {
    if (!deskLocked) return;
    const node = deskRef.current;
    if (!node || typeof node.scrollIntoView !== 'function') return;
    try {
      node.scrollIntoView({ block: 'nearest' });
    } catch {
      // jsdom does not implement scroll positioning.
    }
  }, [deskLocked, activeId]);
  const approvedCaption = [
    'On this page',
    sessionOnThisPage > 0 ? 'From this session' : '',
    sessionOnOtherPages > 0 ? `${formatCount(sessionOnOtherPages)} from earlier pages` : '',
  ].filter(Boolean).join(' · ');
  const detailBody = (
    <Box sx={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: 0, height: '100%', overflow: 'hidden' }}>
      {error || notice ? (
        <Box sx={{ flex: '0 0 auto', pb: 1 }}>
          {error ? <Alert severity="error" sx={{ mb: 1 }} onClose={() => setError(null)}>{error}</Alert> : null}
          {notice ? <Alert severity="success" sx={{ mb: 1 }} onClose={() => setNotice(null)}>{notice}</Alert> : null}
        </Box>
      ) : null}
      <ExpertReviewWizard
        embedded
        rows={rows}
        busyId={busyId}
        askingId={askingId}
        assistanceById={assistanceById}
        selectedIds={selectedIds}
        activeTransactionId={activeId}
        onActiveTransactionId={(id) => {
          setActiveId(id);
          if (!id) setDetailOpen(false);
        }}
        onToggle={(id) => setSelectedIds((current) => (
          current.includes(id) ? current.filter((item) => item !== id) : [...current, id]
        ))}
        onSelectSimilar={(row) => setSelectedIds(similarOpenRows(rows, row).map((item) => item._id))}
        onAskAgent={(row) => { void askAgent(row); }}
        onAskCompany={(row, request) => { void askCompany(row, request); }}
        onCancelRequest={(row) => { void cancelRequest(row); }}
        onReviewReply={(row) => { void reviewReply(row); }}
        onConfirm={(row, scope3Category) => { void confirmOne(row, scope3Category); }}
        onCorrect={(row, draft) => { void correctOne(row, draft); }}
        onReject={(row, reason) => { void rejectOne(row, reason); }}
        reviewNote={note}
        onReviewNote={setNote}
      />
    </Box>
  );
  const boundary = msmeId ? (
    <Accordion sx={{ mt: 2 }}>
      <AccordionSummary expandIcon={<ExpandMoreIcon />} aria-controls="expert-scope3-panel" id="expert-scope3-heading">
        <Typography variant="subtitle2">Reporting boundary</Typography>
      </AccordionSummary>
      <AccordionDetails>
        <ExpertScope3Boundary msmeId={msmeId} />
      </AccordionDetails>
    </Accordion>
  ) : null;
  const orderedCompanies = [...companies].sort((a, b) => {
    const openDelta = Number(b.openRequired > 0) - Number(a.openRequired > 0);
    if (openDelta) return openDelta;
    return String(a.companyName || '').localeCompare(String(b.companyName || ''));
  });
  const companyTitle = summary?.companyName
    || orderedCompanies.find((company) => company.msmeId === msmeId)?.companyName
    || selectedUser?.companyName
    || '';
  const scopeLine = batchId
    ? `Submission batch ${batchId} · Approve eligible rows from Submissions`
    : 'Company ledger';
  const openCompany = (company: CompanySummary) => {
    if (onOpenCompany) onOpenCompany(company);
    else setMsmeId(company.msmeId);
  };

  return (
    <Stack spacing={2} sx={{ minWidth: 0, mb: 3 }}>
      {msmeId && onBackToDirectory && !embedded ? (
        <Button size="small" onClick={onBackToDirectory} sx={{ alignSelf: 'flex-start', textTransform: 'none' }}>
          Back to calculations
        </Button>
      ) : null}
      {msmeId ? (
        <Box>
          {embedded ? null : (
            <Typography variant="h6" component="h2" sx={{ fontWeight: 700, overflowWrap: 'anywhere' }}>
              {companyTitle || 'Company'}
            </Typography>
          )}
          <Typography variant="body2" color="text.secondary">{scopeLine}</Typography>
          {selectedUser ? (
            <Typography variant="caption" color="text.secondary" display="block">
              {`${selectedUser.name} · ${selectedUser.companyName || companyTitle || 'Company'} · ${selectedUser.email}`}
            </Typography>
          ) : null}
        </Box>
      ) : (
        <Box>
          <Typography variant="h6" component="h2" sx={{ fontWeight: 700, mb: 1 }}>Find a company</Typography>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }}>
            <TextField
              size="small"
              label="Company"
              value={companyQuery}
              onChange={(event) => setCompanyQuery(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === 'Enter') {
                  setAppliedCompanyQuery(companyQuery.trim());
                }
              }}
              sx={{ flex: '1 1 220px', maxWidth: 420 }}
            />
            <Button
              size="small"
              variant="outlined"
              onClick={() => setAppliedCompanyQuery(companyQuery.trim())}
              sx={{ textTransform: 'none' }}
            >
              Search
            </Button>
          </Stack>
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
            {companyCursor
              ? 'This company list is only the current page.'
              : 'Counts cover the companies loaded for this search.'}
          </Typography>
        </Box>
      )}
      {msmeId ? (
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' }, gap: 1 }}>
        <MetricCard label="Ledger" pending={awaitingQueue} value={ledgerTotal == null ? '—' : formatCount(ledgerTotal)} caption={ledgerTotal == null ? 'Ledger total was not returned.' : (batchId ? 'Submission batch ledger' : 'Company ledger')} />
        <MetricCard
          label="Uncertain / open"
          pending={awaitingQueue}
          value={openLedger == null ? formatCount(rows.length - pageApproved) : formatCount(openLedger)}
          caption={openLedger != null && ledgerTotal != null
            ? `of ${formatCount(ledgerTotal)} ${queueSummaryScope === 'complete' ? 'in the company' : 'in the selected company'}`
            : 'Company total'}
        />
      </Box>
      ) : loading ? (
        <Stack spacing={1} aria-label="Loading companies">
          {[0, 1, 2].map((key) => <Skeleton key={key} variant="rounded" height={56} />)}
        </Stack>
      ) : null}
      {detailOpen ? null : error ? <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert> : null}
      {detailOpen ? null : notice ? <Alert severity="success" sx={{ mb: 2 }} onClose={() => setNotice(null)}>{notice}</Alert> : null}
      {queueSettled && truncated ? (
        <Alert severity="info" sx={{ mb: 2 }}>
          More transactions are available. This page is not the full queue.
        </Alert>
      ) : null}
      {selectedUser && !selectedUser.msmeId ? (
        <Typography variant="body2">This user has no company ledger, so there are no transactions to correct.</Typography>
      ) : null}
      {!msmeId && !loading && companies.length === 0 ? (
        <Typography variant="body2">No company ledger is waiting for a calculation review.</Typography>
      ) : null}
      {!msmeId && companies.length > 0 ? (
        <Box>
          <Table size="small" aria-label="Calculation company directory">
            <TableHead>
              <TableRow>
                <TableCell>Company</TableCell>
                <TableCell align="right">Open review</TableCell>
                <TableCell>Ledger</TableCell>
                <TableCell>Status</TableCell>
                <TableCell align="right">Action</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {orderedCompanies.map((company) => {
                const clear = Number(company.openRequired) === 0;
                return (
                  <TableRow key={company.msmeId} hover>
                    <TableCell sx={{ fontWeight: 700, overflowWrap: 'anywhere' }}>{company.companyName}</TableCell>
                    <TableCell align="right">{company.openRequired}</TableCell>
                    <TableCell>
                      <Typography variant="caption" display="block">{`Without calculation ${company.counts.withoutCalculation}`}</Typography>
                      <Typography variant="caption" display="block">{`Spend-based ${company.counts.spendBased}`}</Typography>
                    </TableCell>
                    <TableCell>
                      {clear ? <Chip size="small" label="Review clear" variant="outlined" /> : <Chip size="small" label="Review needed" color="warning" variant="outlined" />}
                    </TableCell>
                    <TableCell align="right">
                      <Button
                        size="small"
                        variant="contained"
                        aria-label={`Open calculations for ${company.companyName}`}
                        onClick={() => openCompany(company)}
                        sx={{ textTransform: 'none', boxShadow: 'none' }}
                      >
                        Open calculations
                      </Button>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
          {companyCursor ? (
            <Stack spacing={1} sx={{ mt: 1.5 }}>
              <Typography variant="caption" color="text.secondary">This company list is only the current page. More companies are available.</Typography>
              <Button size="small" variant="outlined" disabled={loadingMoreCompanies} onClick={() => { void loadCompanies(companyCursor); }} sx={{ alignSelf: 'flex-start', textTransform: 'none' }}>
                {loadingMoreCompanies ? 'Loading companies' : 'Load more companies'}
              </Button>
            </Stack>
          ) : null}
        </Box>
      ) : null}
      {msmeId ? (
        <Stack component="section" aria-label="Calculation actions" direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }}>
          <Button variant="outlined" disabled={downloading} onClick={() => { void downloadRows(); }} sx={{ textTransform: 'none' }}>
            {downloading ? 'Downloading' : 'Download uncertain rows'}
          </Button>
          {!batchId ? (
            <Button
              variant="contained"
              color="warning"
              disabled={busyId === 'all' || openRows.length === 0 || bulkBlocked}
              onClick={() => { void confirmOpen(); }}
              sx={{ textTransform: 'none' }}
            >
              {busyId === 'all' ? 'Approving' : 'Approve open calculations for this company'}
            </Button>
          ) : null}
        </Stack>
      ) : null}
      {msmeId && !batchId ? (
        <Typography variant="caption" color="text.secondary">
          Approve all uncertain rows confirms every open row in this company. It does not use this page, the selection, or a shared correction.
        </Typography>
      ) : null}
      {msmeId && !batchId && bulkBlocked ? (
        <Typography variant="body2">Enter a quantity on each row that is still at 0 kg CO2e. Those rows are not approved together.</Typography>
      ) : null}
      {msmeId && selected ? (
        <Typography variant="body2" color="text.secondary">
          {selected.scope === 'all'
            ? 'This company also asked for review of transactions that already have a calculation.'
            : 'Required review covers rows without a calculation and spend-based rows.'}
        </Typography>
      ) : null}
      {selectedRows.length >= 2 ? (
        <ExpertReviewTogether
          key={selectedRows.map((row) => row._id).join('|')}
          rows={selectedRows}
          busy={busyId === 'selected'}
          onCorrect={(draft) => { void correctSelected(draft); }}
          onConfirm={(scope3Category) => { void confirmSelected(scope3Category); }}
          onAsk={(request) => { void askSelected(request); }}
          onClear={() => setSelectedIds([])}
        />
      ) : null}
      {msmeId && (rows.length > 0 || awaitingQueue) ? (
        <Box
          ref={deskRef}
          sx={deskLocked ? {
            mb: 1,
            display: 'flex',
            alignItems: 'stretch',
            alignSelf: 'flex-start',
            gap: 2,
            minWidth: 0,
            position: 'sticky',
            top: 0,
            zIndex: 2,
            height: 'min(720px, calc(100dvh - 220px))',
            maxHeight: 'calc(100dvh - 220px)',
            overflow: 'hidden',
            bgcolor: 'background.paper',
          } : {
            mb: 1,
            display: 'flex',
            alignItems: 'flex-start',
            gap: 2,
            minWidth: 0,
          }}
        >
          <Box sx={{ flex: 1, minWidth: 0, minHeight: 0, display: 'flex', flexDirection: 'column', overflow: deskLocked ? 'hidden' : 'visible' }}>
            <Box sx={{
              position: deskLocked ? 'static' : 'sticky',
              top: 0,
              zIndex: 4,
              flex: '0 0 auto',
              bgcolor: 'background.paper',
              py: 1,
              mb: deskLocked ? 0 : 1,
              borderBottom: 1,
              borderColor: 'divider',
            }}
            >
              <Stack spacing={1}>
                <Typography variant="caption" color="text.secondary" title="Status filters count rows on the page that is loaded. They do not search the rest of the review queue.">
                  Status filters apply to the rows on this page.
                </Typography>
                <ToggleButtonGroup
                  exclusive
                  size="small"
                  aria-label="Page filter. Status filters apply to the rows on this page."
                  title="Status filters apply to the rows on this page."
                  value={pageFilter}
                  onChange={(_event, next: ReviewPageFilter | null) => { if (next) setPageFilter(next); }}
                  sx={{ display: 'flex', flexWrap: 'wrap', maxWidth: '100%' }}
                >
                  {PAGE_FILTERS.map((filter) => {
                    const count = rows.filter((row) => rowMatchesPageFilter(row, filter.id)).length;
                    return (
                      <ToggleButton key={filter.id} value={filter.id}>{`${filter.label} (${count})`}</ToggleButton>
                    );
                  })}
                </ToggleButtonGroup>
                <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
                  <Typography variant="body2">{`Approved ${formatCount(pageApproved)} on this page. ${approvedCaption}`}</Typography>
                  <Typography variant="body2">{`Clarification ${pageClarification} on this page`}</Typography>
                  <Typography variant="body2">
                    {pageFilter === 'all'
                      ? `${selectedOnPage} selected. ${pageEligible.length} eligible on this page.`
                      : `${selectedInFilter} selected in this filter. ${eligibleRows.length} eligible in this filter. ${pageEligible.length} eligible on this page.`}
                  </Typography>
                  <Button
                    size="small"
                    variant="outlined"
                    disabled={(pageFilter === 'all' ? pageEligible : eligibleRows).length === 0}
                    onClick={selectEligible}
                  >
                    {pageFilter === 'all'
                      ? `Select eligible on this page (${pageEligible.length})`
                      : `Select eligible in this filter (${eligibleRows.length})`}
                  </Button>
                  <Button size="small" disabled={selectedIds.length === 0} onClick={() => setSelectedIds([])}>
                    Clear selection
                  </Button>
                  <TextField
                    select
                    size="small"
                    label="Rows per page"
                    value={String(pageSize)}
                    onChange={(event) => setPageSize(reviewPageSize(event.target.value))}
                    sx={{ width: 140 }}
                  >
                    <MenuItem value="50">50</MenuItem>
                    <MenuItem value="100">100</MenuItem>
                    <MenuItem value="200">200</MenuItem>
                  </TextField>
                  {queueTotal != null ? (
                    <Typography variant="body2">
                      {queueTotal === 0
                        ? 'Showing 0 of 0 review transactions'
                        : `Showing ${formatCount(reviewStart)}–${formatCount(reviewEnd)} of ${formatCount(queueTotal)} review transactions`}
                    </Typography>
                  ) : null}
                  <ExpertPager
                    page={pageForLoad}
                    pageCount={displayPageCount}
                    disabled={paging}
                    onPage={showPage}
                  />
                </Stack>
              </Stack>
            </Box>
            <Box ref={scrollRef} data-testid="calculation-table-scroll" sx={{ flex: deskLocked ? 1 : undefined, minHeight: deskLocked ? 0 : undefined, overflow: 'auto', maxWidth: '100%' }}>
              <ExpertReviewTable
                rows={awaitingQueue ? [] : visibleRows}
                allRows={rows}
                selectedIds={selectedIds}
                activeId={detailOpen ? activeId : null}
                loading={awaitingQueue || paging}
                emptyMessage={pageFilter === 'all'
                  ? 'No transactions on this page.'
                  : `No ${PAGE_FILTERS.find((filter) => filter.id === pageFilter)?.label || 'matching'} rows on this page. This filter does not include other pages.`}
                onToggle={(id) => setSelectedIds((current) => (
                  current.includes(id) ? current.filter((item) => item !== id) : [...current, id]
                ))}
                onSelectSimilar={(row) => setSelectedIds(similarOpenRows(rows, row).map((item) => item._id))}
                onOpen={openDetail}
              />
            </Box>
          </Box>
          {detailMounted && desk ? (
            <Box sx={{
              display: detailOpen ? 'flex' : 'none',
              flexDirection: 'column',
              width: { lg: 420, xl: 460 },
              minWidth: 360,
              maxWidth: '38%',
              flex: { lg: '0 1 420px', xl: '0 1 460px' },
              minHeight: 0,
              height: '100%',
              overflow: 'hidden',
              borderLeft: 1,
              borderColor: 'divider',
              pl: 1.5,
            }}
            >
              {detailBody}
            </Box>
          ) : null}
        </Box>
      ) : null}
      {detailMounted && !desk ? (
        <Drawer
          anchor="right"
          open={detailOpen}
          onClose={() => { setDetailOpen(false); setActiveId(null); }}
          ModalProps={{ keepMounted: true }}
          PaperProps={{
            sx: {
              width: { xs: '100%', sm: 480, md: 560 },
              maxWidth: '100%',
              p: 2,
              display: 'flex',
              flexDirection: 'column',
              height: '100%',
              overflow: 'hidden',
            },
          }}
        >
          {detailBody}
        </Drawer>
      ) : null}
      {queueSettled && !paging && msmeId && rows.length === 0 ? (
        <Typography variant="body2">No open rows for this company.</Typography>
      ) : null}
      {boundary}
    </Stack>
  );
};

const MetricCard: React.FC<{ label: string; value: string; caption: string; pending: boolean }> = ({
  label,
  value,
  caption,
  pending,
}) => (
  <Paper variant="outlined" sx={{ p: 1.25, minWidth: 0 }}>
    <Typography variant="caption" color="text.secondary">{label}</Typography>
    {pending ? <Skeleton width={72} height={32} /> : <Typography variant="h6" sx={{ fontWeight: 800 }}>{value}</Typography>}
    {pending ? <Skeleton width="70%" height={18} /> : <Typography variant="caption" color="text.secondary">{caption}</Typography>}
  </Paper>
);

export default ExpertCalculationReview;
