import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Skeleton,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
  useTheme,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import { ConsultantUserSelection } from './ExpertCalculationReview';
import { downloadUncertainWorkbook } from './downloadUncertainWorkbook';

export interface ConsultantUserRow extends ConsultantUserSelection {
  role: string;
  industry?: string;
  registeredProductCount?: number;
  openRequired: number;
  ready: boolean;
  counts: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
}

const MOTION = '@media (prefers-reduced-motion: reduce)';

const finiteCount = (value: unknown) => (
  typeof value === 'number' && Number.isFinite(value) ? value : null
);

const countLabel = (value: unknown) => {
  const count = finiteCount(value);
  return count == null ? 'Unavailable' : String(count);
};

type ReviewState = 'none' | 'needed' | 'clear' | 'unknown';

const reviewState = (user: ConsultantUserRow): ReviewState => {
  if (!user.msmeId) return 'none';
  const open = finiteCount(user.openRequired);
  if (open == null || typeof user.ready !== 'boolean') return 'unknown';
  if (open > 0 || user.ready === false) return 'needed';
  return 'clear';
};

const statusCopy = (state: ReviewState) => {
  if (state === 'none') return { title: 'No company ledger', detail: 'No company ledger' };
  if (state === 'needed') return { title: 'Review needed', detail: 'Review required' };
  if (state === 'clear') return { title: 'Ready to generate', detail: 'Review clear' };
  return { title: 'Unavailable', detail: 'Review status unavailable' };
};

const ExpertUserList: React.FC<{
  onSelect: (user: ConsultantUserRow) => void;
  onOpen?: (user: ConsultantUserRow) => void;
}> = ({ onSelect, onOpen }) => {
  const theme = useTheme();
  const dark = theme.palette.mode === 'dark';
  const text = dark ? '#f1f5f9' : '#0f172a';
  const muted = dark ? '#94a3b8' : '#64748b';
  const cardBg = dark ? theme.palette.background.paper : '#ffffff';
  const border = dark ? 'rgba(241,245,249,0.12)' : 'rgba(15,23,42,0.08)';
  const pageBg = dark ? 'transparent' : '#F8FAFC';
  const [users, setUsers] = useState<ConsultantUserRow[]>([]);
  const [query, setQuery] = useState('');
  const [appliedQuery, setAppliedQuery] = useState('');
  const [cursor, setCursor] = useState<string | null>(null);
  const [totalsScope, setTotalsScope] = useState<'loaded_page' | 'complete'>('loaded_page');
  const [loading, setLoading] = useState(true);
  const [loadingMode, setLoadingMode] = useState<'initial' | 'search' | 'more'>('initial');
  const [error, setError] = useState<string | null>(null);
  const [downloadingId, setDownloadingId] = useState<string | null>(null);

  const load = useCallback(async (append: boolean, nextCursor?: string | null, search = appliedQuery) => {
    setLoading(true);
    setLoadingMode(append ? 'more' : (search ? 'search' : 'initial'));
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/users'), {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        params: { limit: 25, q: search || undefined, cursor: nextCursor || undefined },
      });
      const page: ConsultantUserRow[] = response.data?.data?.users || [];
      setUsers((current) => {
        if (!append) return page;
        const seen = new Set(current.map((user) => `${user.userId}-${user.msmeId || 'none'}`));
        return [...current, ...page.filter((user) => !seen.has(`${user.userId}-${user.msmeId || 'none'}`))];
      });
      setCursor(response.data?.data?.nextCursor || null);
      setTotalsScope(response.data?.data?.totalsScope === 'complete' ? 'complete' : 'loaded_page');
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Failed to load users.');
    } finally {
      setLoading(false);
    }
  }, [appliedQuery]);

  useEffect(() => {
    void load(false);
  }, [load]);

  const submitSearch = () => {
    const next = query.trim();
    if (next === appliedQuery || loading) return;
    setAppliedQuery(next);
  };

  const downloadRows = async (user: ConsultantUserRow) => {
    if (!user.msmeId || downloadingId) return;
    setDownloadingId(user.msmeId);
    setError(null);
    try {
      await downloadUncertainWorkbook(user.msmeId);
    } catch (downloadError: any) {
      setError(downloadError?.response?.data?.message || 'The uncertain transactions workbook could not be downloaded.');
    } finally {
      setDownloadingId(null);
    }
  };

  const surface = {
    bgcolor: cardBg,
    border: `1px solid ${border}`,
    borderRadius: 2,
    minWidth: 0,
  };
  const focusRing = {
    '&:focus-visible': { outline: '2px solid #2e7d32', outlineOffset: 2 },
  };
  const enter = {
    '@keyframes directoryIn': {
      from: { opacity: 0, transform: 'translateY(6px)' },
      to: { opacity: 1, transform: 'none' },
    },
    animation: 'directoryIn 220ms ease both',
    [MOTION]: { animation: 'none' },
  };

  const companyLabel = (user: ConsultantUserRow) => {
    if (!user.msmeId) return 'No company ledger';
    return user.companyName || '—';
  };

  const palette = (state: ReviewState) => {
    if (state === 'needed') return { fg: dark ? '#ffd54f' : '#8a5a00', bg: dark ? 'rgba(255,193,7,0.16)' : 'rgba(255,193,7,0.28)' };
    if (state === 'clear') return { fg: dark ? '#b9f6ca' : '#1b5e20', bg: dark ? 'rgba(76,175,80,0.18)' : 'rgba(76,175,80,0.16)' };
    return { fg: muted, bg: dark ? 'rgba(148,163,184,0.14)' : 'rgba(100,116,139,0.12)' };
  };

  const statusMark = (user: ConsultantUserRow) => {
    const state = reviewState(user);
    const copy = statusCopy(state);
    const colors = palette(state);
    return (
      <Stack spacing={0.25} aria-label={copy.detail} sx={{ alignItems: 'flex-start' }}>
        <Box sx={{ display: 'inline-flex', alignItems: 'center', gap: 0.75, px: 1, py: 0.25, borderRadius: 999, bgcolor: colors.bg, color: colors.fg }}>
          <Box aria-hidden sx={{ width: 8, height: 8, borderRadius: '50%', bgcolor: colors.fg, flex: '0 0 auto' }} />
          <Typography variant="caption" sx={{ fontWeight: 700, color: colors.fg }}>{copy.title}</Typography>
        </Box>
        {copy.detail !== copy.title ? (
          <Typography variant="caption" sx={{ color: muted }}>{copy.detail}</Typography>
        ) : null}
      </Stack>
    );
  };

  const ledger = (user: ConsultantUserRow) => {
    if (!user.msmeId) return <Typography variant="body2" sx={{ color: muted }}>—</Typography>;
    const rows = [
      ['Without calculation', user.counts?.withoutCalculation],
      ['Spend-based', user.counts?.spendBased],
      ['Calculated', user.counts?.calculated],
    ] as const;
    return (
      <Stack spacing={0.25}>
        {rows.map(([label, value]) => (
          <Typography key={label} variant="caption" sx={{ color: text, fontVariantNumeric: 'tabular-nums' }}>
            {`${label} ${countLabel(value)}`}
          </Typography>
        ))}
      </Stack>
    );
  };

  const openReview = (user: ConsultantUserRow) => (
    <Typography variant="body2" sx={{ fontWeight: 700, color: text, fontVariantNumeric: 'tabular-nums' }}>
      {!user.msmeId ? '—' : countLabel(user.openRequired)}
    </Typography>
  );

  const products = (user: ConsultantUserRow) => (
    <Typography variant="body2" sx={{ color: text, fontVariantNumeric: 'tabular-nums' }}>
      {!user.msmeId ? '—' : countLabel(user.registeredProductCount)}
    </Typography>
  );

  const actions = (user: ConsultantUserRow) => {
    const blocked = !user.msmeId;
    const reason = blocked ? 'No company ledger.' : '';
    const busy = downloadingId === user.msmeId;
    return (
      <Stack direction="row" spacing={0.75} useFlexGap flexWrap="wrap" sx={{ justifyContent: { md: 'flex-end' } }}>
        {onOpen ? (
          <Button
            size="small"
            variant="contained"
            aria-disabled={blocked}
            aria-label={blocked ? `Open workspace for ${user.name}. ${reason}` : `Open workspace for ${user.name}`}
            onClick={() => { if (!blocked) onOpen(user); }}
            sx={{ ...focusRing, textTransform: 'none', boxShadow: 'none', minHeight: 40, opacity: blocked ? 0.45 : 1, transition: 'background-color 150ms ease, opacity 150ms ease', [MOTION]: { transition: 'none' } }}
          >
            Open workspace
          </Button>
        ) : null}
        <Button
          size="small"
          variant="outlined"
          aria-disabled={blocked}
          aria-label={blocked ? `Review ${user.name}. ${reason}` : `Review ${user.name}`}
          onClick={() => { if (!blocked) onSelect(user); }}
          sx={{ ...focusRing, textTransform: 'none', minHeight: 40, opacity: blocked ? 0.45 : 1, transition: 'background-color 150ms ease, border-color 150ms ease, opacity 150ms ease', [MOTION]: { transition: 'none' } }}
        >
          {`Review ${user.name}`}
        </Button>
        <Button
          size="small"
          variant="text"
          aria-disabled={blocked || busy}
          aria-label={blocked ? `Download uncertain rows for ${user.name}. ${reason}` : `Download uncertain rows for ${user.name}`}
          onClick={() => { if (!blocked && !busy) void downloadRows(user); }}
          sx={{ ...focusRing, textTransform: 'none', minHeight: 40, opacity: blocked || busy ? 0.45 : 1, transition: 'background-color 150ms ease, opacity 150ms ease', [MOTION]: { transition: 'none' } }}
        >
          {busy ? 'Downloading' : 'Download uncertain rows'}
        </Button>
      </Stack>
    );
  };

  const identity = (user: ConsultantUserRow) => {
    const initials = user.name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]?.toUpperCase() || '').join('');
    return (
      <Stack direction="row" spacing={1} alignItems="flex-start" sx={{ minWidth: 0 }}>
        {initials ? (
          <Box aria-hidden sx={{ width: 32, height: 32, borderRadius: '50%', flexShrink: 0, display: 'grid', placeItems: 'center', bgcolor: 'rgba(76,175,80,0.16)', color: '#2e7d32', fontSize: 12, fontWeight: 700 }}>
            {initials}
          </Box>
        ) : null}
        <Box sx={{ minWidth: 0 }}>
          <Typography variant="body2" sx={{ fontWeight: 700, color: text, overflowWrap: 'anywhere' }}>{user.name}</Typography>
          <Typography variant="caption" sx={{ display: 'block', color: muted, overflowWrap: 'anywhere' }}>{user.email}</Typography>
        </Box>
      </Stack>
    );
  };

  return (
    <Box sx={{ bgcolor: pageBg, borderRadius: 2, p: { xs: 0, md: 0.5 }, ...enter }}>
      {error ? (
        <Alert
          severity="error"
          sx={{ mb: 2 }}
          action={<Button color="inherit" size="small" onClick={() => void load(false)} sx={focusRing}>Retry</Button>}
        >
          {error}
        </Alert>
      ) : null}
      <Box sx={{ ...surface, p: { xs: 1.5, md: 2 }, mb: 1.5 }}>
        <Typography variant="h6" component="h2" id="company-directory-search-label" sx={{ fontWeight: 650, letterSpacing: '-0.02em', color: text, mb: 1 }}>
          Find a company or user
        </Typography>
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
          <TextField
            id="company-directory-search"
            size="small"
            placeholder="Find a user, email or company"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') submitSearch();
            }}
            inputProps={{ 'aria-labelledby': 'company-directory-search-label' }}
            sx={{
              flex: '1 1 220px',
              maxWidth: { xs: '100%', sm: 420 },
              minWidth: 0,
              '& .MuiOutlinedInput-root': { transition: 'border-color 160ms ease, box-shadow 160ms ease', [MOTION]: { transition: 'none' } },
            }}
          />
          <Button
            size="small"
            variant="outlined"
            onClick={submitSearch}
            disabled={loading}
            aria-busy={loading && loadingMode === 'search'}
            sx={{ ...focusRing, minHeight: 40, textTransform: 'none' }}
          >
            {loading && loadingMode === 'search' ? 'Searching' : 'Search'}
          </Button>
        </Box>
        <Typography variant="caption" sx={{ display: 'block', mt: 1.25, color: muted }}>
          {totalsScope === 'complete'
            ? 'Counts cover every company that matched this search.'
            : 'Counts cover the companies loaded so far.'}
        </Typography>
      </Box>

      {loading && users.length === 0 ? (
        <Stack spacing={1} aria-label="Loading companies">
          {[0, 1, 2, 3].map((key) => <Skeleton key={key} variant="rounded" height={72} sx={{ borderRadius: 2 }} />)}
        </Stack>
      ) : null}
      {!loading && !error && users.length === 0 ? (
        <Typography variant="body2" role="status" sx={{ color: text, px: 0.5 }}>
          {appliedQuery ? 'No users match this search.' : 'No users are available for consultant review.'}
        </Typography>
      ) : null}

      {users.length > 0 ? (
        <>
          <Box sx={{ ...surface, display: { xs: 'none', md: 'block' }, overflowX: 'auto' }}>
            <Table size="small" aria-label="Company directory" sx={{ width: '100%', minWidth: { md: 720, lg: 960 } }}>
              <TableHead>
                <TableRow>
                  <TableCell>User</TableCell>
                  <TableCell>Company</TableCell>
                  <TableCell sx={{ display: { md: 'none', lg: 'table-cell' } }}>Industry</TableCell>
                  <TableCell align="right" sx={{ display: { md: 'none', lg: 'table-cell' } }}>Registered products</TableCell>
                  <TableCell align="right">Open review</TableCell>
                  <TableCell sx={{ display: { md: 'none', lg: 'table-cell' } }}>Ledger composition</TableCell>
                  <TableCell>Review status</TableCell>
                  <TableCell align="right">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {users.map((user) => (
                  <TableRow
                    key={`table-${user.userId}-${user.msmeId || 'none'}`}
                    hover
                    sx={{ transition: 'background-color 140ms ease', [MOTION]: { transition: 'none' } }}
                  >
                    <TableCell>{identity(user)}</TableCell>
                    <TableCell sx={{ color: text, overflowWrap: 'anywhere', maxWidth: 220 }}>{companyLabel(user)}</TableCell>
                    <TableCell sx={{ display: { md: 'none', lg: 'table-cell' }, color: text }}>{user.industry || '—'}</TableCell>
                    <TableCell align="right" sx={{ display: { md: 'none', lg: 'table-cell' } }}>{products(user)}</TableCell>
                    <TableCell align="right">{openReview(user)}</TableCell>
                    <TableCell sx={{ display: { md: 'none', lg: 'table-cell' } }}>{ledger(user)}</TableCell>
                    <TableCell>{statusMark(user)}</TableCell>
                    <TableCell align="right">{actions(user)}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
            <Typography variant="caption" sx={{ display: 'block', px: 2, py: 1, color: muted }}>
              Ledger composition lists class totals. Those totals include rows that have already been reviewed. Open review is the queue that still needs a consultant.
            </Typography>
          </Box>
          <Stack spacing={1.25} sx={{ display: { xs: 'flex', md: 'none' } }}>
            {users.map((user) => (
              <Box key={`card-${user.userId}-${user.msmeId || 'none'}`} sx={{ ...surface, p: 1.5 }}>
                {identity(user)}
                <Typography variant="body2" sx={{ mt: 1, color: text, overflowWrap: 'anywhere' }}>{companyLabel(user)}</Typography>
                <Typography variant="caption" sx={{ display: 'block', color: muted, overflowWrap: 'anywhere' }}>
                  {user.industry ? user.industry : '—'}
                </Typography>
                <Stack direction="row" spacing={2} sx={{ mt: 1 }}>
                  <Box>
                    <Typography variant="caption" sx={{ color: muted }}>Registered products</Typography>
                    {products(user)}
                  </Box>
                  <Box>
                    <Typography variant="caption" sx={{ color: muted }}>Open review</Typography>
                    {openReview(user)}
                  </Box>
                </Stack>
                <Typography variant="caption" sx={{ display: 'block', mt: 1, color: muted }}>Ledger composition</Typography>
                {ledger(user)}
                <Box sx={{ mt: 1 }}>{statusMark(user)}</Box>
                <Box sx={{ mt: 1.25 }}>{actions(user)}</Box>
              </Box>
            ))}
          </Stack>
        </>
      ) : null}
      {cursor ? (
        <Button
          sx={{ mt: 2, ...focusRing, textTransform: 'none' }}
          onClick={() => void load(true, cursor)}
          disabled={loading}
          aria-busy={loading && loadingMode === 'more'}
        >
          {loading && loadingMode === 'more' ? 'Loading more companies' : 'Load more companies'}
        </Button>
      ) : null}
    </Box>
  );
};

export default ExpertUserList;
