import React, { useCallback, useEffect, useState } from 'react';
import { Alert, Box, Button, Skeleton, Stack, Table, TableBody, TableCell, TableHead, TableRow, Typography } from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

export interface OpenCalculationRow {
  id: string;
  msmeId: string;
  companyName?: string;
  batchId?: string;
  description?: string;
  category?: string;
}

interface OpenCalculationPage {
  transactions?: OpenCalculationRow[];
  nextCursor?: string | null;
  summary?: { openRequired?: number };
  totalsScope?: string;
}

const ExpertOpenCalculations: React.FC<{
  onOpen: (row: OpenCalculationRow) => void;
}> = ({ onOpen }) => {
  const [rows, setRows] = useState<OpenCalculationRow[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [openRequired, setOpenRequired] = useState<number | null>(null);
  const [scope, setScope] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async (append: boolean, nextCursor?: string | null) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/open-calculations'), {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        params: { limit: 50, cursor: nextCursor || undefined },
      });
      const page = (response.data?.data || {}) as OpenCalculationPage;
      const incoming = Array.isArray(page.transactions) ? page.transactions : [];
      setRows((current) => {
        if (!append) return incoming;
        const seen = new Set(current.map((row) => row.id));
        return [...current, ...incoming.filter((row) => row?.id && !seen.has(row.id))];
      });
      setCursor(page.nextCursor || null);
      setOpenRequired(typeof page.summary?.openRequired === 'number' ? page.summary.openRequired : null);
      setScope(page.totalsScope || '');
    } catch (loadError: any) {
      if (!append) {
        setRows([]);
        setCursor(null);
        setOpenRequired(null);
        setScope('');
      }
      setError(loadError?.response?.data?.message || 'Open calculations could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load(false);
  }, [load]);

  return (
    <Stack spacing={2}>
      <Typography variant="h6" component="h2">Open calculations</Typography>
      <Typography variant="body2" color="text.secondary">
        Read-only rows counted by the open-required rule. This list does not approve a company.
      </Typography>
      {scope === 'complete' && openRequired != null ? (
        <Typography variant="body2">Open required: {openRequired}</Typography>
      ) : null}
      {error ? (
        <Alert severity="error" action={<Button color="inherit" size="small" onClick={() => void load(false)}>Retry</Button>}>
          {error}
        </Alert>
      ) : null}
      {loading && rows.length === 0 ? <Skeleton variant="rounded" height={88} aria-label="Loading open calculations" /> : null}
      {!loading && !error && rows.length === 0 ? <Typography variant="body2">No open calculations.</Typography> : null}
      {rows.length > 0 ? (
        <Box sx={{ overflowX: 'auto' }}>
          <Table size="small" aria-label="Open calculations" sx={{ minWidth: 760 }}>
            <TableHead>
              <TableRow>
                <TableCell>Company</TableCell>
                <TableCell>Company ID</TableCell>
                <TableCell>Transaction</TableCell>
                <TableCell>Batch</TableCell>
                <TableCell>Description</TableCell>
                <TableCell />
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map((row) => (
                <TableRow key={row.id} hover>
                  <TableCell>{row.companyName || 'Company name unavailable'}</TableCell>
                  <TableCell sx={{ fontFamily: 'monospace' }}>{row.msmeId}</TableCell>
                  <TableCell sx={{ fontFamily: 'monospace' }}>{row.id}</TableCell>
                  <TableCell sx={{ fontFamily: 'monospace' }}>{row.batchId || '—'}</TableCell>
                  <TableCell>{row.description || row.category || '—'}</TableCell>
                  <TableCell>
                    <Button
                      size="small"
                      onClick={() => onOpen(row)}
                      sx={{ '&:focus-visible': { outline: '2px solid #2e7d32', outlineOffset: 2 } }}
                    >
                      Open
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </Box>
      ) : null}
      {cursor ? (
        <Button onClick={() => void load(true, cursor)} disabled={loading} sx={{ alignSelf: 'flex-start', '&:focus-visible': { outline: '2px solid #2e7d32', outlineOffset: 2 } }}>
          Load more
        </Button>
      ) : null}
    </Stack>
  );
};

export default ExpertOpenCalculations;
