import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Drawer,
  MenuItem,
  Skeleton,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import ExpertPager from './ExpertPager';

export interface FactorLineageSummary {
  id?: string;
  source?: string;
  sourceVersion?: string;
  sourceMatch?: string;
  factor?: number | null;
  unit?: string;
}

export interface FactorTransactionSummary {
  description?: string;
  date?: string | null;
  vendor?: string;
  amount?: number | null;
  currency?: string;
  category?: string;
  subcategory?: string;
  quantity?: number | string | null;
  unit?: string;
  kgCO2e?: number | null;
  factorVersion?: string;
  factorLineage?: FactorLineageSummary;
}

export interface FactorExceptionQueueRow {
  exceptionId: string;
  exceptionType: string;
  severity?: string;
  status?: string;
  reason?: string;
  message?: string;
  factorId?: string;
  attemptedFactorId?: string;
  factorVersion?: string;
  activityCategory?: string;
  quantity?: number | string | null;
  unit?: string;
  evidenceDocumentId?: string;
  batchId?: string;
  detectedAt?: string;
  transactionId: string;
  msmeId: string;
  description?: string;
  companyName?: string;
  blocksReport?: boolean;
  transaction?: FactorTransactionSummary | null;
}

interface CompanySummary {
  msmeId: string;
  companyName: string;
  open: number;
  blocking: number;
  lineageBlocked?: number;
}

interface BulkProgress {
  done: number;
  total: number;
  resolved: number;
  failed: { transactionId: string; label: string; message: string }[];
  finished: boolean;
}

const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('token')}` });

type ExceptionPageSize = 25 | 50 | 100 | 200;

const exceptionPageSize = (value: string): ExceptionPageSize => {
  if (value === '200') return 200;
  if (value === '100') return 100;
  if (value === '50') return 50;
  return 25;
};

const formatCount = (value: number) => value.toLocaleString('en-US');

const storedFactor = (row: FactorExceptionQueueRow) => (row.factorId || row.attemptedFactorId || '').trim();

const factorRequired = (row: FactorExceptionQueueRow) => (
  row.exceptionType !== 'source_verification_required' && row.exceptionType !== 'outdated_factor'
);

const unpublishedCell = (row: FactorExceptionQueueRow) => /no_published_cell/i.test(row.reason || '');

const rowLabel = (row: FactorExceptionQueueRow) => row.description || row.transaction?.description || row.transactionId || 'transaction';

const RESOLVE_PRESETS = [
  {
    label: 'Verified applied factor',
    reason: 'Verified the applied factor for this activity.',
    evidence: 'expert-source-verification',
  },
  {
    label: 'Confirmed standard registry factor',
    reason: 'Confirmed the standard registry factor for this activity.',
    evidence: 'expert-registry-confirmation',
  },
];

const showValue = (value: unknown) => (
  value == null || value === '' ? 'Unavailable' : String(value)
);

const summaryOf = (row: FactorExceptionQueueRow): FactorTransactionSummary => row.transaction || {
  description: row.description,
  category: row.activityCategory,
  quantity: row.quantity,
  unit: row.unit,
  factorVersion: row.factorVersion,
  factorLineage: {
    id: storedFactor(row),
    sourceVersion: '',
  },
};

const versionMissing = (row: FactorExceptionQueueRow) => {
  const summary = summaryOf(row);
  return !String(summary.factorLineage?.sourceVersion || summary.factorVersion || row.factorVersion || '').trim();
};

const factorGuidance = (required: boolean) => (
  required
    ? 'This exception type needs an active approved factor id. Entering an id forces recalculation and requires the lineage id to match.'
    : 'Leave this blank to accept the stored factor without recalculating. Entering an id forces recalculation and requires the lineage id to match.'
);

const TransactionSummaryCard: React.FC<{ row: FactorExceptionQueueRow }> = ({ row }) => {
  const summary = summaryOf(row);
  const lineage = summary.factorLineage || {};
  const amount = summary.amount == null
    ? 'Unavailable'
    : `${summary.amount}${summary.currency ? ` ${summary.currency}` : ''}`;
  const when = summary.date ? new Date(summary.date).toLocaleString() : 'Unavailable';
  return (
    <Box sx={{ border: 1, borderColor: 'divider', borderRadius: 1, p: 1.5 }}>
      <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>Transaction and calculation summary</Typography>
      <Typography variant="body2">{`Vendor ${showValue(summary.vendor)}`}</Typography>
      <Typography variant="body2">{`Date ${when}`}</Typography>
      <Typography variant="body2">{`Amount ${amount}`}</Typography>
      <Typography variant="body2">{`Category ${showValue(summary.category)}${summary.subcategory ? ` / ${summary.subcategory}` : ''}`}</Typography>
      <Typography variant="body2">{`Quantity ${showValue(summary.quantity)} ${summary.unit || ''}`.trim()}</Typography>
      <Typography variant="body2">{`kg CO2e ${showValue(summary.kgCO2e)}`}</Typography>
      <Typography variant="body2">{`Factor ${showValue(lineage.id)} · ${showValue(lineage.factor)} ${lineage.unit || ''}`.trim()}</Typography>
      <Typography variant="body2">{`Source ${showValue(lineage.source)} · ${showValue(lineage.sourceVersion)}`}</Typography>
      <Typography variant="body2">{`Source match ${showValue(lineage.sourceMatch)}`}</Typography>
    </Box>
  );
};

const postResolve = (row: FactorExceptionQueueRow, reason: string, evidence: string, factorId: string) => (
  axios.post(buildApiUrl(`/expert/transactions/${row.transactionId}/factor-exception/resolve`), {
    msmeId: row.msmeId,
    batchId: row.batchId || undefined,
    factorId: factorId || undefined,
    reason,
    evidenceDocumentId: evidence,
    recalculate: Boolean(factorId),
  }, { headers: authHeaders() })
);

const errorMessage = (error: unknown, fallback: string) => {
  const message = (error as { response?: { data?: { message?: unknown } } })?.response?.data?.message;
  return typeof message === 'string' && message ? message : fallback;
};

const ExpertFactorExceptionQueue: React.FC<{
  onOpen: (row: FactorExceptionQueueRow) => void;
  onCloseException?: () => void;
  companyId?: string;
  focusTransactionId?: string;
}> = ({ onOpen, onCloseException, companyId = '', focusTransactionId = '' }) => {
  const [companies, setCompanies] = useState<CompanySummary[]>([]);
  const [totalOpen, setTotalOpen] = useState(0);
  const [totalBlocking, setTotalBlocking] = useState(0);
  const [picked, setPicked] = useState('');
  const [rows, setRows] = useState<FactorExceptionQueueRow[]>([]);
  const [pageSize, setPageSize] = useState<ExceptionPageSize>(25);
  const [page, setPage] = useState(1);
  const [detailTotal, setDetailTotal] = useState<number | null>(null);
  const [detailBlocking, setDetailBlocking] = useState<number | null>(null);
  const [pageCount, setPageCount] = useState(1);
  const [loadingCompanies, setLoadingCompanies] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeTransactionId, setActiveTransactionId] = useState(focusTransactionId);
  const [offPageRow, setOffPageRow] = useState<FactorExceptionQueueRow | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [reason, setReason] = useState('');
  const [evidence, setEvidence] = useState('');
  const [factorInput, setFactorInput] = useState('');
  const [formError, setFormError] = useState('');
  const [resolving, setResolving] = useState(false);
  const [bulkOpen, setBulkOpen] = useState(false);
  const [bulkReason, setBulkReason] = useState('');
  const [bulkEvidence, setBulkEvidence] = useState('');
  const [bulkFactor, setBulkFactor] = useState('');
  const [bulkError, setBulkError] = useState('');
  const [bulkProgress, setBulkProgress] = useState<BulkProgress | null>(null);
  const [bulkRunning, setBulkRunning] = useState(false);
  const pendingSelect = useRef<'' | 'first' | 'last'>('');
  const loadedFor = useRef('');

  const selected = companies.find((company) => company.msmeId === picked) || null;
  const activeRow = rows.find((row) => row.transactionId === activeTransactionId)
    || (offPageRow?.transactionId === activeTransactionId ? offPageRow : null);
  const activeIndex = rows.findIndex((row) => row.transactionId === activeTransactionId);
  const previousRow = activeIndex > 0 ? rows[activeIndex - 1] : null;
  const nextRow = activeIndex >= 0 && activeIndex + 1 < rows.length ? rows[activeIndex + 1] : null;
  const selectedRows = rows.filter((row) => selectedIds.includes(row.transactionId));
  const bulkNeedsFactor = selectedRows.some(factorRequired);
  const factorAnchor = activeRow || selectedRows[0] || null;
  const factorKey = factorAnchor ? storedFactor(factorAnchor) : '';

  const loadCompanies = useCallback(async () => {
    setLoadingCompanies(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/factor-exceptions/companies'), {
        headers: authHeaders(),
      });
      const data = response.data?.data || {};
      setCompanies(Array.isArray(data.companies) ? data.companies : []);
      setTotalOpen(Number(data.totalOpen) || 0);
      setTotalBlocking(Number(data.totalBlocking) || 0);
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Factor exception companies could not be loaded.');
    } finally {
      setLoadingCompanies(false);
    }
  }, []);

  const loadExceptions = useCallback(async (msmeId: string, pageNumber: number, size: number) => {
    if (!msmeId) return;
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/factor-exceptions'), {
        headers: authHeaders(),
        params: { limit: size, msmeId, page: pageNumber },
      });
      const data = response.data?.data || {};
      const loaded: FactorExceptionQueueRow[] = data.exceptions || [];
      const reportedTotal = Number(data.totalOpen);
      const reportedBlocking = Number(data.totalBlocking);
      const reportedCount = Number(data.pageCount);
      loadedFor.current = `${msmeId}|${pageNumber}|${size}`;
      setRows(loaded);
      setDetailTotal(Number.isFinite(reportedTotal) ? reportedTotal : loaded.length);
      setDetailBlocking(Number.isFinite(reportedBlocking) ? reportedBlocking : null);
      setPageCount(Number.isFinite(reportedCount) && reportedCount > 0 ? reportedCount : 1);
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Factor exceptions could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadCompanies();
  }, [loadCompanies]);

  useEffect(() => {
    if (companyId) setPicked(companyId);
  }, [companyId]);

  useEffect(() => {
    setActiveTransactionId(focusTransactionId);
  }, [focusTransactionId]);

  useEffect(() => {
    setReason('');
    setEvidence('');
    setFactorInput('');
    setFormError('');
  }, [activeTransactionId]);

  const detailKey = `${picked}|${pageSize}`;
  const detailRef = useRef(detailKey);
  const detailChanged = detailRef.current !== detailKey;
  if (detailChanged) {
    detailRef.current = detailKey;
    if (page !== 1) setPage(1);
  }
  const pageForLoad = detailChanged ? 1 : page;
  const exceptionTotal = detailTotal ?? selected?.open ?? 0;
  const rangeStart = exceptionTotal > 0 && rows.length > 0 ? ((pageForLoad - 1) * pageSize) + 1 : 0;
  const rangeEnd = rangeStart > 0 ? Math.min(exceptionTotal, rangeStart + rows.length - 1) : 0;

  useEffect(() => {
    if (!picked) {
      setRows([]);
      setDetailTotal(null);
      setDetailBlocking(null);
      setPageCount(1);
      loadedFor.current = '';
      return;
    }
    void loadExceptions(picked, pageForLoad, pageSize);
  }, [picked, pageForLoad, pageSize, loadExceptions]);

  useEffect(() => {
    if (!pendingSelect.current || loading) return;
    const mode = pendingSelect.current;
    pendingSelect.current = '';
    if (rows.length === 0) {
      setActiveTransactionId('');
      onCloseException?.();
      return;
    }
    const row = mode === 'first' ? rows[0] : rows[rows.length - 1];
    setActiveTransactionId(row.transactionId);
    onOpen(row);
  }, [rows, loading, onOpen, onCloseException]);

  useEffect(() => {
    if (!activeTransactionId || !picked || loading) return;
    if (rows.some((row) => row.transactionId === activeTransactionId)) {
      setOffPageRow(null);
      return;
    }
    if (loadedFor.current !== `${picked}|${pageForLoad}|${pageSize}`) return;
    let cancelled = false;
    const loadOne = async () => {
      try {
        const response = await axios.get(buildApiUrl(`/expert/transactions/${activeTransactionId}/factor-exception`), {
          headers: authHeaders(),
          params: { msmeId: picked },
        });
        const exception = response.data?.data?.exception;
        if (cancelled || !exception?.exceptionType) return;
        const summary = response.data?.data?.transaction || null;
        setOffPageRow({
          exceptionId: String(exception.exceptionId || activeTransactionId),
          exceptionType: exception.exceptionType,
          severity: exception.severity,
          status: exception.status,
          reason: exception.reason,
          message: exception.message,
          factorId: exception.factorId,
          attemptedFactorId: exception.attemptedFactorId,
          factorVersion: exception.factorVersion,
          activityCategory: exception.activityCategory,
          quantity: exception.quantity,
          unit: exception.unit,
          evidenceDocumentId: exception.evidenceDocumentId,
          blocksReport: exception.blocksReport !== false,
          transactionId: activeTransactionId,
          msmeId: picked,
          description: summary?.description || '',
          companyName: selected?.companyName || '',
          transaction: summary,
        });
      } catch (loadError: unknown) {
        if (!cancelled) setFormError(errorMessage(loadError, 'The factor exception could not be loaded.'));
      }
    };
    void loadOne();
    return () => {
      cancelled = true;
    };
  }, [activeTransactionId, picked, loading, rows, pageForLoad, pageSize, selected?.companyName]);

  const openRow = (row: FactorExceptionQueueRow) => {
    setActiveTransactionId(row.transactionId);
    onOpen(row);
  };

  const closeDrawer = () => {
    setActiveTransactionId('');
    setOffPageRow(null);
    onCloseException?.();
  };

  const showPage = (nextPage: number) => {
    if (!pendingSelect.current) {
      setActiveTransactionId('');
      onCloseException?.();
    }
    setPage(nextPage);
  };

  const noteResolved = (row: FactorExceptionQueueRow) => {
    const blockingDrop = row.blocksReport ? 1 : 0;
    const nextTotal = Math.max(0, (detailTotal ?? rows.length) - 1);
    setDetailTotal(nextTotal);
    setPageCount(Math.max(1, Math.ceil(nextTotal / pageSize) || 1));
    setDetailBlocking((current) => (current == null ? current : Math.max(0, current - blockingDrop)));
    setTotalOpen((current) => Math.max(0, current - 1));
    setTotalBlocking((current) => Math.max(0, current - blockingDrop));
    setCompanies((list) => list.map((company) => (
      company.msmeId === row.msmeId
        ? {
          ...company,
          open: Math.max(0, company.open - 1),
          blocking: Math.max(0, company.blocking - blockingDrop),
        }
        : company
    )));
    setSelectedIds((current) => current.filter((id) => id !== row.transactionId));
  };

  const advanceAfterResolve = (row: FactorExceptionQueueRow) => {
    const index = rows.findIndex((item) => item.transactionId === row.transactionId);
    const following = index >= 0 ? rows[index + 1] : undefined;
    const earlier = index > 0 ? rows[index - 1] : undefined;
    noteResolved(row);
    if (following) {
      setRows((current) => current.filter((item) => item.transactionId !== row.transactionId));
      setActiveTransactionId(following.transactionId);
      onOpen(following);
      return;
    }
    setRows((current) => current.filter((item) => item.transactionId !== row.transactionId));
    if (pageForLoad < pageCount) {
      pendingSelect.current = 'last';
      void loadExceptions(picked, pageForLoad, pageSize);
      return;
    }
    if (earlier) {
      setActiveTransactionId(earlier.transactionId);
      onOpen(earlier);
      return;
    }
    if (pageForLoad > 1) {
      pendingSelect.current = 'last';
      setPage(pageForLoad - 1);
      return;
    }
    setActiveTransactionId('');
    onCloseException?.();
  };

  const resolveActive = async () => {
    if (!activeRow || resolving) return;
    const note = reason.trim();
    const proof = evidence.trim();
    const factorId = factorInput.trim();
    if (note.length < 8 || !proof) return;
    if (factorRequired(activeRow) && !factorId) return;
    setResolving(true);
    setFormError('');
    try {
      await postResolve(activeRow, note, proof, factorId);
      advanceAfterResolve(activeRow);
    } catch (resolveError: unknown) {
      setFormError(errorMessage(resolveError, 'The exception was not resolved.'));
    } finally {
      setResolving(false);
    }
  };

  const toggleSelected = (transactionId: string) => {
    setSelectedIds((current) => (
      current.includes(transactionId)
        ? current.filter((id) => id !== transactionId)
        : [...current, transactionId]
    ));
  };

  const selectIds = (ids: string[]) => {
    setSelectedIds(Array.from(new Set(ids)));
  };

  const resolveSelected = async () => {
    const note = bulkReason.trim();
    const proof = bulkEvidence.trim();
    const factorId = bulkFactor.trim();
    if (note.length < 8 || !proof || selectedRows.length === 0) return;
    if (bulkNeedsFactor && !factorId) {
      setBulkError('These exceptions need an active approved factor id.');
      return;
    }
    setBulkRunning(true);
    setBulkError('');
    const progress: BulkProgress = { done: 0, total: selectedRows.length, resolved: 0, failed: [], finished: false };
    setBulkProgress(progress);
    for (const row of selectedRows) {
      try {
        await postResolve(row, note, proof, factorId);
        progress.resolved += 1;
      } catch (resolveError: unknown) {
        progress.failed.push({
          transactionId: row.transactionId,
          label: rowLabel(row),
          message: errorMessage(resolveError, 'The exception was not resolved.'),
        });
      }
      progress.done += 1;
      setBulkProgress({ ...progress, failed: progress.failed.slice() });
    }
    progress.finished = true;
    setBulkProgress({ ...progress, failed: progress.failed.slice() });
    setBulkRunning(false);
    const failedIds = new Set(progress.failed.map((item) => item.transactionId));
    const activeFailed = failedIds.has(activeTransactionId);
    if (!activeFailed) {
      setActiveTransactionId('');
      onCloseException?.();
    }
    setSelectedIds(selectedRows.filter((row) => failedIds.has(row.transactionId)).map((row) => row.transactionId));
    await loadCompanies();
    if (picked) await loadExceptions(picked, pageForLoad, pageSize);
  };

  const lineageBlocked = picked
    ? Number(companies.find((company) => company.msmeId === picked)?.lineageBlocked || 0)
    : companies.reduce((sum, company) => sum + Number(company.lineageBlocked || 0), 0);
  const activeNeedsFactor = activeRow ? factorRequired(activeRow) : false;
  const resolveDisabled = resolving
    || reason.trim().length < 8
    || evidence.trim().length === 0
    || (activeNeedsFactor && factorInput.trim().length === 0);
  const bulkDisabled = bulkRunning
    || Boolean(bulkProgress?.finished && bulkProgress.failed.length === 0)
    || selectedRows.length === 0
    || bulkReason.trim().length < 8
    || bulkEvidence.trim().length === 0
    || (bulkNeedsFactor && bulkFactor.trim().length === 0);

  return (
    <Stack spacing={2}>
      <Typography variant="body2" color="text.secondary">
        {loadingCompanies
          ? 'Loading company totals.'
          : `${totalBlocking} blocking exceptions and ${totalOpen} open or assigned exceptions across ${companies.length} ${companies.length === 1 ? 'company' : 'companies'}. These totals cover every open exception, not one page.`}
      </Typography>
      {lineageBlocked > 0 ? (
        <Alert severity="error">
          {`${lineageBlocked} transaction${lineageBlocked === 1 ? ' has a stored emission factor that cannot' : 's have stored emission factors that cannot'} be used in an official report. The factor-exception queue can be empty while these rows stay closed until a source version is stored.`}
        </Alert>
      ) : null}
      {error ? (
        <Alert
          severity="error"
          action={(
            <Button color="inherit" size="small" onClick={() => { void loadCompanies(); if (picked) void loadExceptions(picked, pageForLoad, pageSize); }}>
              Retry
            </Button>
          )}
        >
          {error}
        </Alert>
      ) : null}
      {!picked ? (
        <>
          {loadingCompanies ? (
            <Stack spacing={1} aria-label="Loading companies">
              {[0, 1, 2].map((key) => <Skeleton key={key} variant="rounded" height={72} />)}
            </Stack>
          ) : null}
          {!loadingCompanies && companies.length === 0 ? (
            <Typography variant="body2">No open factor exceptions.</Typography>
          ) : null}
          {companies.map((company) => (
            <Box key={company.msmeId} sx={{ border: 1, borderColor: 'divider', borderRadius: 1, p: 2 }}>
              <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} justifyContent="space-between" alignItems={{ sm: 'center' }}>
                <Box>
                  <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>{company.companyName}</Typography>
                  <Typography variant="body2" color="text.secondary">
                    {`${company.blocking} blocking · ${company.open} open or assigned${company.lineageBlocked ? ` · ${company.lineageBlocked} missing a source version` : ''}`}
                  </Typography>
                </Box>
                <Button
                  variant="contained"
                  aria-label={`Open exceptions for ${company.companyName}`}
                  onClick={() => setPicked(company.msmeId)}
                >
                  Open exceptions
                </Button>
              </Stack>
            </Box>
          ))}
        </>
      ) : (
        <>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }}>
            <Button size="small" onClick={() => { setPicked(''); closeDrawer(); }} sx={{ textTransform: 'none', alignSelf: 'flex-start' }}>
              Back to all companies
            </Button>
            <TextField
              select
              size="small"
              label="Company"
              value={picked}
              onChange={(event) => setPicked(event.target.value)}
              sx={{ minWidth: 240 }}
            >
              {companies.map((company) => (
                <MenuItem key={company.msmeId} value={company.msmeId}>{company.companyName}</MenuItem>
              ))}
              {!selected && picked ? <MenuItem value={picked}>Selected company</MenuItem> : null}
            </TextField>
          </Stack>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }} flexWrap="wrap" useFlexGap>
            <Typography variant="body2">
              {selected ? `${selected.companyName}. ` : ''}
              {loading && rows.length === 0
                ? 'Loading exceptions for this company.'
                : exceptionTotal === 0
                  ? 'Showing 0 of 0 exceptions.'
                  : `Showing ${formatCount(rangeStart)}–${formatCount(rangeEnd)} of ${formatCount(exceptionTotal)} exceptions.`}
              {detailBlocking != null ? ` ${formatCount(detailBlocking)} blocking.` : ''}
            </Typography>
            <TextField
              select
              size="small"
              label="Rows per page"
              value={String(pageSize)}
              onChange={(event) => setPageSize(exceptionPageSize(event.target.value))}
              sx={{ width: 150 }}
            >
              <MenuItem value="25">25</MenuItem>
              <MenuItem value="50">50</MenuItem>
              <MenuItem value="100">100</MenuItem>
              <MenuItem value="200">200</MenuItem>
            </TextField>
          </Stack>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }} flexWrap="wrap" useFlexGap>
            <Button size="small" disabled={rows.length === 0 || !rows.some(unpublishedCell)} onClick={() => selectIds(rows.filter(unpublishedCell).map((row) => row.transactionId))}>
              Select unpublished-cell rows
            </Button>
            <Button size="small" disabled={!factorKey} onClick={() => selectIds(rows.filter((row) => storedFactor(row) === factorKey).map((row) => row.transactionId))}>
              Select same factor
            </Button>
            <Button size="small" variant="contained" disabled={selectedRows.length === 0} onClick={() => { setBulkOpen(true); setBulkProgress(null); setBulkError(''); }}>
              {`Resolve ${selectedRows.length} selected`}
            </Button>
            <Typography variant="caption" color="text.secondary">
              Selection is the current page. One reason and one evidence reference are sent to each selected row.
            </Typography>
          </Stack>
          {loading && rows.length === 0 ? (
            <Stack spacing={1} aria-label="Loading factor exceptions">
              {[0, 1, 2].map((key) => <Skeleton key={key} variant="rounded" height={88} />)}
            </Stack>
          ) : null}
          {!loading && detailTotal === 0 ? <Typography variant="body2">No open factor exceptions for this company.</Typography> : null}
          {rows.length > 0 ? (
            <Box sx={{ overflowX: 'auto' }}>
              <Table size="small" aria-label="Factor exceptions" sx={{ minWidth: 760 }}>
                <TableHead>
                  <TableRow>
                    <TableCell padding="checkbox">
                      <Checkbox
                        checked={rows.length > 0 && selectedRows.length === rows.length}
                        indeterminate={selectedRows.length > 0 && selectedRows.length < rows.length}
                        onChange={() => selectIds(selectedRows.length === rows.length ? [] : rows.map((row) => row.transactionId))}
                        inputProps={{ 'aria-label': 'Select all exceptions on this page' }}
                      />
                    </TableCell>
                    <TableCell>Company</TableCell>
                    <TableCell>Transaction</TableCell>
                    <TableCell>Type</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell>Severity</TableCell>
                    <TableCell>Blocks report</TableCell>
                    <TableCell>Detected</TableCell>
                    <TableCell>Reason</TableCell>
                    <TableCell>Message</TableCell>
                    <TableCell>Factor</TableCell>
                    <TableCell>Evidence</TableCell>
                    <TableCell>Batch</TableCell>
                    <TableCell>Review</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {rows.map((row) => (
                    <TableRow key={row.exceptionId} selected={row.transactionId === activeTransactionId}>
                      <TableCell padding="checkbox">
                        <Checkbox
                          checked={selectedIds.includes(row.transactionId)}
                          onChange={() => toggleSelected(row.transactionId)}
                          inputProps={{ 'aria-label': `Select ${rowLabel(row)}` }}
                        />
                      </TableCell>
                      <TableCell>{row.companyName || selected?.companyName || 'Company name unavailable'}</TableCell>
                      <TableCell>
                        {row.description || row.transactionId}
                        {focusTransactionId && row.transactionId === focusTransactionId ? (
                          <Typography variant="caption" display="block">Opened from activity classification.</Typography>
                        ) : null}
                      </TableCell>
                      <TableCell>{row.exceptionType}</TableCell>
                      <TableCell>{row.status || 'Status unavailable'}</TableCell>
                      <TableCell>{row.severity || 'unspecified'}</TableCell>
                      <TableCell>{row.blocksReport ? 'Yes' : 'No'}</TableCell>
                      <TableCell>{row.detectedAt ? new Date(row.detectedAt).toLocaleString() : 'Detected date unavailable'}</TableCell>
                      <TableCell>{row.reason || 'Reason unavailable'}</TableCell>
                      <TableCell>{row.message || 'Message unavailable'}</TableCell>
                      <TableCell>{[row.factorId, row.attemptedFactorId].filter(Boolean).join(' · ') || 'Factor unavailable'}</TableCell>
                      <TableCell>{row.evidenceDocumentId || 'No evidence id'}</TableCell>
                      <TableCell>{row.batchId || 'Batch unavailable'}</TableCell>
                      <TableCell>
                        <Button
                          size="small"
                          variant="contained"
                          aria-label={`Review ${row.description || 'transaction'} for ${row.companyName || 'company'}`}
                          onClick={() => openRow(row)}
                          disabled={!row.transactionId || !row.msmeId}
                        >
                          Review transaction
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </Box>
          ) : null}
          <ExpertPager
            page={pageForLoad}
            pageCount={pageCount}
            disabled={loading}
            onPage={showPage}
          />
        </>
      )}
      <Drawer anchor="right" open={Boolean(activeRow)} onClose={closeDrawer} PaperProps={{ sx: { width: { xs: '100%', sm: 440 }, p: 2 } }}>
        {activeRow ? (
          <Stack spacing={1.5} role="dialog" aria-label="Resolve exception">
            <Typography variant="h6" component="h2">Resolve exception</Typography>
            <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>{rowLabel(activeRow)}</Typography>
            <TransactionSummaryCard row={activeRow} />
            {versionMissing(activeRow) ? (
              <Alert severity="warning">
                This row has no stored source version. An official report also needs a source version on the factor lineage. Resolving source verification copies the version from the active registry factor when the lineage id matches.
              </Alert>
            ) : null}
            <Typography variant="body2">{`Type ${activeRow.exceptionType}`}</Typography>
            <Typography variant="body2">{activeRow.reason || activeRow.message || 'Reason unavailable'}</Typography>
            <Typography variant="body2">{storedFactor(activeRow) ? `Stored factor ${storedFactor(activeRow)}` : 'Stored factor unavailable'}</Typography>
            <Typography variant="body2">{`Blocks report: ${activeRow.blocksReport ? 'Yes' : 'No'}`}</Typography>
            <Typography variant="body2">
              {`Status ${activeRow.status || 'open'}. Assigned exceptions still count toward the blocking total until they are resolved.`}
            </Typography>
            <Stack direction="row" spacing={1}>
              <Button size="small" aria-label="Previous exception" disabled={!previousRow && pageForLoad <= 1} onClick={() => {
                if (previousRow) openRow(previousRow);
                else if (pageForLoad > 1) {
                  pendingSelect.current = 'last';
                  setPage(pageForLoad - 1);
                }
              }}
              >
                Previous
              </Button>
              <Button size="small" aria-label="Next exception" disabled={!nextRow && pageForLoad >= pageCount} onClick={() => {
                if (nextRow) openRow(nextRow);
                else if (pageForLoad < pageCount) {
                  pendingSelect.current = 'first';
                  setPage(pageForLoad + 1);
                }
              }}
              >
                Next
              </Button>
            </Stack>
            <TextField
              size="small"
              label="Approved factor id"
              value={factorInput}
              onChange={(event) => setFactorInput(event.target.value)}
              helperText={factorGuidance(activeNeedsFactor)}
            />
            <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
              {RESOLVE_PRESETS.map((preset) => (
                <Button key={preset.label} size="small" onClick={() => { setReason(preset.reason); setEvidence(preset.evidence); }}>
                  {preset.label}
                </Button>
              ))}
            </Stack>
            <TextField
              size="small"
              label="Resolution reason"
              value={reason}
              onChange={(event) => setReason(event.target.value)}
              helperText="At least 8 characters."
            />
            <TextField
              size="small"
              label="Evidence reference"
              value={evidence}
              onChange={(event) => setEvidence(event.target.value)}
              helperText={evidence.trim() ? ' ' : 'An evidence reference is required.'}
            />
            {formError ? <Alert severity="error">{formError}</Alert> : null}
            <Stack direction="row" spacing={1}>
              <Button variant="contained" disabled={resolveDisabled} onClick={() => { void resolveActive(); }}>
                {resolving ? 'Resolving' : 'Resolve exception'}
              </Button>
              <Button onClick={closeDrawer}>Close</Button>
            </Stack>
          </Stack>
        ) : null}
      </Drawer>
      <Dialog open={bulkOpen} onClose={() => { if (!bulkRunning) setBulkOpen(false); }} aria-labelledby="bulk-resolve-title" fullWidth maxWidth="sm">
        <DialogTitle id="bulk-resolve-title">Resolve selected exceptions</DialogTitle>
        <DialogContent>
          <Stack spacing={1.5} sx={{ pt: 1 }}>
            <Typography variant="body2">
              {`${selectedRows.length} selected exception${selectedRows.length === 1 ? '' : 's'} on this page. Each one is resolved with this reason and evidence reference.`}
            </Typography>
            {selectedRows.some(versionMissing) ? (
              <Alert severity="warning">
                One or more selected rows have no stored source version. Resolving source verification copies the active registry version when the lineage id matches.
              </Alert>
            ) : null}
            <TextField
              size="small"
              label="Approved factor id"
              value={bulkFactor}
              onChange={(event) => setBulkFactor(event.target.value)}
              helperText={bulkNeedsFactor
                ? 'One or more selected rows need an active approved factor id. Entering an id forces recalculation and requires the lineage id to match. It is applied to every selected row.'
                : factorGuidance(false)}
            />
            <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
              {RESOLVE_PRESETS.map((preset) => (
                <Button key={preset.label} size="small" onClick={() => { setBulkReason(preset.reason); setBulkEvidence(preset.evidence); }}>
                  {preset.label}
                </Button>
              ))}
            </Stack>
            <TextField
              size="small"
              label="Resolution reason"
              value={bulkReason}
              onChange={(event) => setBulkReason(event.target.value)}
              helperText="At least 8 characters."
            />
            <TextField
              size="small"
              label="Evidence reference"
              value={bulkEvidence}
              onChange={(event) => setBulkEvidence(event.target.value)}
            />
            {bulkError ? <Alert severity="error">{bulkError}</Alert> : null}
            {bulkProgress ? (
              <Alert severity={bulkProgress.finished && bulkProgress.failed.length === 0 ? 'success' : bulkProgress.finished ? 'warning' : 'info'} aria-live="polite">
                <Typography variant="body2">
                  {bulkProgress.finished
                    ? `Resolved ${bulkProgress.resolved}. Failed ${bulkProgress.failed.length}.`
                    : `Resolving ${bulkProgress.done + 1} of ${bulkProgress.total}.`}
                </Typography>
                {bulkProgress.failed.map((item) => (
                  <Typography key={item.transactionId} variant="body2">{`${item.label}: ${item.message}`}</Typography>
                ))}
              </Alert>
            ) : null}
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setBulkOpen(false)} disabled={bulkRunning}>Close</Button>
          <Button variant="contained" disabled={bulkDisabled} onClick={() => { void resolveSelected(); }}>
            Resolve matching exceptions
          </Button>
        </DialogActions>
      </Dialog>
    </Stack>
  );
};

export default ExpertFactorExceptionQueue;
