import React, { useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  Skeleton,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
  useTheme,
} from '@mui/material';
import InboxOutlinedIcon from '@mui/icons-material/InboxOutlined';
import FactCheckOutlinedIcon from '@mui/icons-material/FactCheckOutlined';
import WarningAmberOutlinedIcon from '@mui/icons-material/WarningAmberOutlined';
import TuneOutlinedIcon from '@mui/icons-material/TuneOutlined';
import ChatBubbleOutlineIcon from '@mui/icons-material/ChatBubbleOutline';
import ReceiptLongOutlinedIcon from '@mui/icons-material/ReceiptLongOutlined';
import { ConsultantUserRow } from './ExpertUserList';
import { ExpertSection } from './ExpertPortalLayout';

interface SubmissionCounts {
  total?: number;
  approved?: number;
  pending?: number;
  processing?: number;
  waitingForBill?: number;
  additionalInformation?: number;
  failed?: number;
  reviewable?: number;
  bulkApproval?: { eligible?: number };
}

export interface OverviewSubmission {
  batchId: string;
  msmeId: string;
  status: string;
  source?: string;
  fileName?: string;
  companyName?: string;
  submittedAt?: string | null;
  counts?: SubmissionCounts;
}

interface MetricBlock {
  totalsScope?: string;
  [key: string]: unknown;
}

interface CompanyRow {
  msmeId?: unknown;
  companyName?: unknown;
  registeredProductCount?: unknown;
  openCalculations?: unknown;
  submissionsNotApproved?: unknown;
  blockingFactorExceptions?: unknown;
}

interface ExpertOverviewProps {
  users: ConsultantUserRow[];
  summary?: {
    submissions?: MetricBlock & { notApproved?: number };
    calculations?: MetricBlock & { openRequired?: number };
    clarifications?: MetricBlock & { open?: number };
    bills?: MetricBlock & { required?: number };
    factorExceptions?: MetricBlock & { open?: number };
    classification?: MetricBlock & { held?: number };
    priority?: OverviewSubmission[];
    companies?: { totalsScope?: string; nextCursor?: string | null; rows?: CompanyRow[] };
    recentSubmissions?: OverviewSubmission[];
  } | null;
  companyTotalsScope: 'loaded_page' | 'complete';
  summaryError?: string | null;
  usersError?: string | null;
  loading?: boolean;
  onRetry?: () => void;
  onSection: (section: ExpertSection) => void;
  onOpenDestination?: (destination: { section: ExpertSection; view: '' | 'open-submissions' | 'clarifications' | 'bills' | 'open-calculations' }) => void;
  onOpenSubmission: (row: OverviewSubmission) => void;
  onOpenCalculations?: (company: { msmeId: string }) => void;
  onLoadMoreCompanies?: () => void;
  loadingMoreCompanies?: boolean;
  companyPageError?: string | null;
  onReview: (user: ConsultantUserRow) => void;
}

const MOTION = '@media (prefers-reduced-motion: reduce)';

const useNarrowOverview = () => {
  const [narrow, setNarrow] = useState(false);
  useEffect(() => {
    if (typeof window.matchMedia !== 'function') return undefined;
    const query = window.matchMedia('(max-width: 899px)');
    if (!query || typeof query.matches !== 'boolean') return undefined;
    const apply = () => setNarrow(query.matches);
    apply();
    query.addEventListener?.('change', apply);
    return () => query.removeEventListener?.('change', apply);
  }, []);
  return narrow;
};

const completeValue = (block: MetricBlock | undefined, field: string) => {
  if (!block || block.totalsScope !== 'complete') return null;
  const value = block[field];
  return typeof value === 'number' ? value : null;
};

const batchKey = (row: OverviewSubmission) => (
  row.msmeId && row.batchId ? `${row.msmeId}|${row.batchId}` : ''
);

const submittedMillis = (value?: string | null) => {
  if (!value) return null;
  const time = new Date(value).getTime();
  return Number.isNaN(time) ? null : time;
};

const exactSubmitted = (value?: string | null) => {
  const time = submittedMillis(value);
  if (time == null) return '';
  return new Date(time).toLocaleString();
};

const relativeSubmitted = (value?: string | null) => {
  const time = submittedMillis(value);
  if (time == null) return '';
  const delta = Date.now() - time;
  if (delta < 0) return exactSubmitted(value);
  const minute = 60 * 1000;
  const hour = 60 * minute;
  const day = 24 * hour;
  if (delta < minute) return 'Just now';
  if (delta < hour) {
    const count = Math.floor(delta / minute);
    return `${count} minute${count === 1 ? '' : 's'} ago`;
  }
  if (delta < day) {
    const count = Math.floor(delta / hour);
    return `${count} hour${count === 1 ? '' : 's'} ago`;
  }
  const count = Math.floor(delta / day);
  return `${count} day${count === 1 ? '' : 's'} ago`;
};

const sourceLabel = (source?: string) => {
  const value = String(source || '').trim();
  if (!value) return '';
  if (value === 'connector') return 'Data Connector';
  if (value === 'excel') return 'Excel';
  return value;
};

const statusTone = (status: string): 'success' | 'warning' | 'error' | 'default' => {
  const value = status.toLowerCase();
  if (value.includes('fail')) return 'error';
  if (value.includes('approv')) return 'success';
  if (value.includes('partial') || value.includes('information') || value.includes('bill') || value.includes('pending') || value.includes('review')) return 'warning';
  return 'default';
};

const initialsOf = (name: string) => {
  const parts = name.trim().split(/\s+/).filter(Boolean).slice(0, 2);
  return parts.map((part) => part.charAt(0).toUpperCase()).join('');
};

const sortPriority = (rows: OverviewSubmission[]) => rows.slice().sort((left, right) => {
  const leftTime = submittedMillis(left.submittedAt);
  const rightTime = submittedMillis(right.submittedAt);
  const leftRank = leftTime == null ? Number.MAX_SAFE_INTEGER : leftTime;
  const rightRank = rightTime == null ? Number.MAX_SAFE_INTEGER : rightTime;
  if (leftRank !== rightRank) return leftRank - rightRank;
  return String(left.batchId || '').localeCompare(String(right.batchId || ''));
});

const ExpertOverview: React.FC<ExpertOverviewProps> = ({
  users,
  summary,
  companyTotalsScope,
  summaryError,
  usersError,
  loading = false,
  onRetry,
  onSection,
  onOpenDestination,
  onOpenSubmission,
  onOpenCalculations,
  onLoadMoreCompanies,
  loadingMoreCompanies = false,
  companyPageError,
  onReview,
}) => {
  const theme = useTheme();
  const dark = theme.palette.mode === 'dark';
  const text = dark ? '#f1f5f9' : '#0f172a';
  const muted = dark ? '#94a3b8' : '#64748b';
  const cardBg = dark ? theme.palette.background.paper : '#ffffff';
  const border = dark ? 'rgba(241,245,249,0.12)' : 'rgba(15,23,42,0.08)';
  const pageBg = dark ? 'transparent' : '#F8FAFC';
  const hoverBg = dark ? 'rgba(255,255,255,0.04)' : '#F8FAFC';
  const narrow = useNarrowOverview();
  const openUsers = users.filter((user) => user.msmeId && user.openRequired > 0).slice(0, 5);
  const submissionsComplete = summary?.submissions?.totalsScope === 'complete';
  const priority = submissionsComplete ? sortPriority(Array.isArray(summary?.priority) ? summary.priority : []).slice(0, 10) : [];
  const openKeys = new Set(priority.map(batchKey).filter(Boolean));
  const recent = submissionsComplete
    ? (Array.isArray(summary?.recentSubmissions) ? summary.recentSubmissions : []).filter((row) => {
      const key = batchKey(row);
      return !key || !openKeys.has(key);
    })
    : [];
  const showSource = priority.some((row) => sourceLabel(row.source));
  const bothFailed = Boolean(summaryError && usersError);

  const surface = {
    bgcolor: cardBg,
    border: `1px solid ${border}`,
    borderRadius: 2,
    minWidth: 0,
  };
  const enter = (delay: number) => ({
    '@keyframes overviewIn': {
      from: { opacity: 0, transform: 'translateY(6px)' },
      to: { opacity: 1, transform: 'none' },
    },
    animation: `overviewIn 220ms ease ${delay}ms both`,
    [MOTION]: { animation: 'none' },
  });
  const focusRing = {
    '&:focus-visible': { outline: '2px solid #2e7d32', outlineOffset: 2 },
  };

  const retryAction = onRetry
    ? <Button color="inherit" size="small" onClick={onRetry}>Retry</Button>
    : undefined;

  const cards = [
    { label: 'Submissions not approved', value: completeValue(summary?.submissions, 'notApproved'), hint: 'Stamped batches that are not approved', section: 'queue' as ExpertSection, view: 'open-submissions' as const, icon: <InboxOutlinedIcon fontSize="small" />, primary: true },
    { label: 'Open calculations', value: completeValue(summary?.calculations, 'openRequired'), hint: 'Rows counted by the open-required rule. Opens the global row list.', section: 'review' as ExpertSection, view: 'open-calculations' as const, icon: <FactCheckOutlinedIcon fontSize="small" />, primary: true },
    { label: 'Factor exceptions', value: completeValue(summary?.factorExceptions, 'open'), hint: 'Open or assigned exceptions that block an official report', section: 'exceptions' as ExpertSection, view: '' as const, icon: <WarningAmberOutlinedIcon fontSize="small" />, primary: true },
    { label: 'Emission review rows', value: completeValue(summary?.classification, 'held'), hint: 'Activity-factor hold, admin emission review, or spend amount times a factor', section: 'classification' as ExpertSection, view: '' as const, icon: <TuneOutlinedIcon fontSize="small" />, primary: true },
    { label: 'Clarifications', value: completeValue(summary?.clarifications, 'open'), hint: 'Open requests and answered replies. Reviewed and cancelled requests are not included.', section: 'review' as ExpertSection, view: 'clarifications' as const, icon: <ChatBubbleOutlineIcon fontSize="small" />, primary: false },
    { label: 'Bills required', value: completeValue(summary?.bills, 'required'), hint: 'High-value bill hold', section: 'review' as ExpertSection, view: 'bills' as const, icon: <ReceiptLongOutlinedIcon fontSize="small" />, primary: false },
  ];

  const metricGrid = (primary: boolean) => (
    <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr', lg: primary ? 'repeat(4, minmax(0, 1fr))' : 'repeat(4, minmax(0, 1fr))' }, gap: 1.5 }}>
      {loading ? cards.filter((card) => card.primary === primary).map((card) => (
        <Skeleton key={card.label} variant="rounded" height={primary ? 118 : 92} sx={{ borderRadius: 2 }} />
      )) : cards.filter((card) => card.primary === primary).map((card) => {
        const unavailable = card.value == null;
        const caption = summaryError ? 'This count could not be loaded.' : unavailable ? 'Complete count was not returned.' : card.hint;
        return (
          <Box
            key={card.label}
            component="button"
            type="button"
            onClick={() => (onOpenDestination ? onOpenDestination({ section: card.section, view: card.view }) : onSection(card.section))}
            aria-label={`${card.label}: ${unavailable ? 'Unavailable' : card.value}. ${caption}`}
            sx={{
              ...surface,
              ...focusRing,
              appearance: 'none',
              textAlign: 'left',
              cursor: 'pointer',
              p: primary ? 2 : 1.5,
              color: text,
              transition: 'border-color 180ms ease, background-color 180ms ease, transform 180ms ease',
              '&:hover': { borderColor: 'rgba(76,175,80,0.45)', bgcolor: hoverBg, transform: 'translateY(-1px)' },
              [MOTION]: { transition: 'none', '&:hover': { transform: 'none' } },
            }}
          >
            <Stack direction="row" spacing={1} alignItems="center" sx={{ color: muted, mb: 0.75 }}>
              <Box sx={{ color: '#2e7d32', display: 'flex' }}>{card.icon}</Box>
              <Typography variant="body2" sx={{ fontWeight: 600, lineHeight: 1.3 }}>{card.label}</Typography>
            </Stack>
            <Typography sx={{ fontWeight: 650, fontSize: primary ? { xs: '1.75rem', sm: '2rem' } : { xs: '1.25rem', sm: '1.375rem' }, lineHeight: 1.1, fontVariantNumeric: 'tabular-nums', color: unavailable ? muted : text }}>
              {unavailable ? 'Unavailable' : card.value}
            </Typography>
            <Typography variant="caption" sx={{ display: 'block', mt: 0.75, color: muted }}>{caption}</Typography>
          </Box>
        );
      })}
    </Box>
  );

  const submittedCell = (row: OverviewSubmission) => {
    const relative = relativeSubmitted(row.submittedAt);
    const exact = exactSubmitted(row.submittedAt);
    if (!relative) return <Typography variant="body2" sx={{ color: muted }}>Submitted time unavailable</Typography>;
    return (
      <Typography component="time" variant="body2" dateTime={row.submittedAt || undefined} title={exact} aria-label={exact} sx={{ fontVariantNumeric: 'tabular-nums', color: text }}>
        {relative}
      </Typography>
    );
  };

  const openLabel = (row: OverviewSubmission) => {
    const company = row.companyName?.trim();
    return company ? `Open submission for ${company}` : 'Open selected submission';
  };
  const submissionAction = (row: OverviewSubmission) => (
    <Button
      size="small"
      variant="contained"
      aria-label={openLabel(row)}
      onClick={() => onOpenSubmission(row)}
      sx={{ ...focusRing, textTransform: 'none', boxShadow: 'none', transition: 'background-color 150ms ease', [MOTION]: { transition: 'none' } }}
    >
      Open
    </Button>
  );

  return (
    <Stack spacing={3} sx={{ bgcolor: pageBg, borderRadius: 2, minWidth: 0 }}>
      {bothFailed ? (
        <Alert severity="error" action={retryAction}>{summaryError}</Alert>
      ) : null}
      {summaryError && !usersError ? (
        <Alert severity="error" action={retryAction}>{summaryError}</Alert>
      ) : null}

      <Stack spacing={1.5} sx={enter(0)}>
        {metricGrid(true)}
        {metricGrid(false)}
      </Stack>

      <Box component="section" aria-labelledby="overview-open-submissions" sx={{ ...surface, ...enter(40), p: { xs: 1.5, md: 2 } }}>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} justifyContent="space-between" alignItems={{ sm: 'center' }} sx={{ mb: 1.5 }}>
          <Box>
            <Typography id="overview-open-submissions" variant="h6" component="h2" sx={{ fontWeight: 650, letterSpacing: '-0.02em', color: text }}>Open submissions</Typography>
            <Typography variant="body2" sx={{ color: muted }}>Start with the oldest submissions awaiting review.</Typography>
          </Box>
          <Button size="small" onClick={() => onSection('queue')} sx={{ ...focusRing, alignSelf: 'flex-start' }}>All submissions</Button>
        </Stack>
        {loading ? (
          <Stack spacing={1} aria-hidden>
            {[0, 1, 2].map((key) => <Skeleton key={key} variant="rounded" height={52} />)}
          </Stack>
        ) : summaryError ? null : !submissionsComplete ? (
          <Typography variant="body2" role="status">Open submissions are unavailable until the summary is complete.</Typography>
        ) : priority.length === 0 ? (
          <Typography variant="body2" role="status">You&apos;re all caught up. No submissions are awaiting review.</Typography>
        ) : narrow ? (
          <Stack spacing={1}>
            {priority.map((row) => (
              <Box key={batchKey(row) || row.batchId} sx={{ border: `1px solid ${border}`, borderRadius: 1.5, p: 1.5, minWidth: 0 }}>
                <Typography variant="subtitle2" sx={{ fontWeight: 650, color: text, overflowWrap: 'anywhere' }}>{row.companyName || 'Company name unavailable'}</Typography>
                <Typography variant="caption" sx={{ display: 'block', color: muted, mb: 1 }}>{row.batchId}</Typography>
                <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" alignItems="center" sx={{ mb: 1 }}>
                  <Chip size="small" color={statusTone(row.status)} variant="outlined" label={row.status} />
                  {submittedCell(row)}
                  {sourceLabel(row.source) ? <Typography variant="caption" sx={{ color: muted }}>{sourceLabel(row.source)}</Typography> : null}
                </Stack>
                {submissionAction(row)}
              </Box>
            ))}
          </Stack>
        ) : (
          <Table size="small" sx={{ '& td, & th': { borderColor: border } }}>
            <TableHead>
              <TableRow>
                <TableCell sx={{ color: muted, fontWeight: 600 }}>Company and batch</TableCell>
                <TableCell sx={{ color: muted, fontWeight: 600 }}>Status</TableCell>
                <TableCell sx={{ color: muted, fontWeight: 600 }}>Submitted</TableCell>
                {showSource ? <TableCell sx={{ color: muted, fontWeight: 600 }}>Source</TableCell> : null}
                <TableCell align="right" sx={{ color: muted, fontWeight: 600 }}>Action</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {priority.map((row) => (
                <TableRow key={batchKey(row) || `${row.companyName}-${row.status}`} hover sx={{ transition: 'background-color 140ms ease', [MOTION]: { transition: 'none' } }}>
                  <TableCell>
                    <Typography variant="body2" sx={{ fontWeight: 650, color: text, overflowWrap: 'anywhere' }}>{row.companyName || 'Company name unavailable'}</Typography>
                    <Typography variant="caption" sx={{ color: muted }}>{row.batchId}</Typography>
                  </TableCell>
                  <TableCell><Chip size="small" color={statusTone(row.status)} variant="outlined" label={row.status} /></TableCell>
                  <TableCell>{submittedCell(row)}</TableCell>
                  {showSource ? <TableCell><Typography variant="body2" sx={{ color: text }}>{sourceLabel(row.source) || '—'}</Typography></TableCell> : null}
                  <TableCell align="right">{submissionAction(row)}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </Box>

      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', lg: 'minmax(0, 1.5fr) minmax(0, 1fr)' }, gap: 2.5, alignItems: 'start', minWidth: 0 }}>
        <Box component="section" aria-labelledby="overview-company-progress" sx={{ ...surface, ...enter(80), p: { xs: 1.5, md: 2 }, minWidth: 0 }}>
          <Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" spacing={1} sx={{ mb: 0.5 }}>
            <Typography id="overview-company-progress" variant="h6" component="h2" sx={{ fontWeight: 650, letterSpacing: '-0.02em', color: text }}>Company progress</Typography>
            <Button size="small" onClick={() => onSection('companies')} sx={{ ...focusRing, alignSelf: 'flex-start' }}>Open the company directory</Button>
          </Stack>
          <Typography variant="body2" role="status" sx={{ color: text }}>
            {summaryError || !summary
              ? 'Company progress is unavailable.'
              : 'Registered companies and the review counts returned for this page.'}
          </Typography>
          {!summaryError && summary?.companies?.rows?.length ? (
            <Stack spacing={1} sx={{ mt: 1.5 }}>
              {summary.companies.totalsScope !== 'complete' ? (
                <Typography variant="caption" sx={{ color: muted }}>This is not every company. Open the directory to page through the rest.</Typography>
              ) : null}
              {summary.companies.nextCursor ? (
                <Typography variant="caption" sx={{ color: muted }}>This company list is only the current page.</Typography>
              ) : null}
              {summary.companies.rows.map((row) => {
                const companyName = String(row.companyName || 'Company name unavailable');
                const msmeId = String(row.msmeId || '');
                return (
                  <Stack key={msmeId || companyName} direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" alignItems={{ sm: 'center' }} spacing={1}>
                    <Box sx={{ minWidth: 0 }}>
                      <Typography variant="body2" sx={{ fontWeight: 650, color: text, overflowWrap: 'anywhere' }}>{companyName}</Typography>
                      <Typography variant="caption" sx={{ color: muted }}>
                        {`${row.openCalculations ?? 0} open calculations · ${row.submissionsNotApproved ?? 0} submissions not approved · ${row.blockingFactorExceptions ?? 0} blocking factor exceptions`}
                      </Typography>
                    </Box>
                    <Button
                      size="small"
                      variant="contained"
                      disabled={!msmeId}
                      aria-label={`Calculation for ${companyName}`}
                      onClick={() => { if (msmeId && onOpenCalculations) onOpenCalculations({ msmeId }); }}
                      sx={{ ...focusRing, flexShrink: 0, textTransform: 'none', boxShadow: 'none' }}
                    >
                      Calculation
                    </Button>
                  </Stack>
                );
              })}
              {summary.companies.nextCursor ? (
                <Button
                  size="small"
                  variant="outlined"
                  disabled={loadingMoreCompanies || !onLoadMoreCompanies}
                  onClick={() => onLoadMoreCompanies?.()}
                  sx={{ ...focusRing, alignSelf: 'flex-start', textTransform: 'none' }}
                >
                  {loadingMoreCompanies ? 'Loading companies' : 'Load more companies'}
                </Button>
              ) : null}
              {companyPageError ? <Alert severity="error">{companyPageError}</Alert> : null}
            </Stack>
          ) : null}
          {!summaryError && summary && (summary.companies?.rows?.length || 0) === 0 ? (
            <Typography variant="body2" sx={{ mt: 1, color: text }}>No registered companies were returned.</Typography>
          ) : null}
        </Box>

        <Stack spacing={2.5} sx={{ minWidth: 0 }}>
          <Box sx={{ ...surface, ...enter(100), p: { xs: 1.5, md: 2 } }}>
            <Stack direction="row" justifyContent="space-between" alignItems="center" spacing={1} sx={{ mb: 0.5 }}>
              <Typography variant="h6" component="h2" sx={{ fontWeight: 650, letterSpacing: '-0.02em', color: text }}>Next reviews</Typography>
              <Button size="small" onClick={() => onSection('companies')} sx={focusRing}>All companies</Button>
            </Stack>
            <Typography variant="body2" sx={{ color: muted, mb: 1.5 }}>People with open calculation work. Review calculations opens the company-wide calculation desk. It does not open a submission batch.</Typography>
            {loading ? (
              <Stack spacing={1} aria-hidden>
                {[0, 1].map((key) => <Skeleton key={key} variant="rounded" height={64} />)}
              </Stack>
            ) : usersError ? (
              bothFailed ? null : <Alert severity="error" action={retryAction}>{usersError}</Alert>
            ) : openUsers.length === 0 ? (
              <Typography variant="body2" role="status">
                {companyTotalsScope === 'complete'
                  ? 'No reviewers have open work right now.'
                  : 'No one on this page of users has open review work.'}
              </Typography>
            ) : (
              <Stack spacing={1}>
                {companyTotalsScope === 'loaded_page' ? (
                  <Typography variant="caption" sx={{ color: muted }}>From the first page of users. This is not a global ranking.</Typography>
                ) : null}
                {openUsers.map((user) => {
                  const label = user.name || user.email || 'Reviewer';
                  const mark = initialsOf(user.name || user.email || '');
                  return (
                    <Stack key={user.userId} direction="row" spacing={1.25} alignItems="center" sx={{ minWidth: 0 }}>
                      {mark ? (
                        <Box aria-hidden sx={{ width: 32, height: 32, borderRadius: '50%', flexShrink: 0, display: 'grid', placeItems: 'center', bgcolor: 'rgba(76,175,80,0.16)', color: '#2e7d32', fontSize: 12, fontWeight: 700 }}>
                          {mark}
                        </Box>
                      ) : null}
                      <Box sx={{ flex: 1, minWidth: 0 }}>
                        <Typography variant="body2" sx={{ fontWeight: 650, color: text, overflowWrap: 'anywhere' }}>{label}</Typography>
                        <Typography variant="caption" sx={{ color: muted, overflowWrap: 'anywhere' }}>
                          {user.companyName ? `${user.companyName} · ` : ''}{`${user.openRequired} open`}
                        </Typography>
                      </Box>
                      <Button size="small" variant="contained" aria-label={`Review calculations for ${label}`} onClick={() => onReview(user)} sx={{ ...focusRing, flexShrink: 0, textTransform: 'none', boxShadow: 'none' }}>
                        Review calculations
                      </Button>
                    </Stack>
                  );
                })}
              </Stack>
            )}
          </Box>

          <Box sx={{ ...surface, ...enter(120), p: { xs: 1.5, md: 2 } }}>
            <Typography variant="h6" component="h2" sx={{ fontWeight: 650, letterSpacing: '-0.02em', color: text }}>Recent submissions</Typography>
            <Typography variant="body2" sx={{ color: muted, mb: 1.5 }}>The latest submissions received across your companies.</Typography>
            {loading ? (
              <Stack spacing={1} aria-hidden>
                {[0, 1].map((key) => <Skeleton key={key} variant="rounded" height={56} />)}
              </Stack>
            ) : summaryError ? null : !submissionsComplete ? (
              <Typography variant="body2" role="status">Recent submissions are unavailable until the summary is complete.</Typography>
            ) : recent.length === 0 ? (
              <Typography variant="body2" role="status">No recent submissions are available.</Typography>
            ) : (
              <Stack spacing={1.25}>
                {recent.map((row) => (
                  <Stack key={`recent-${batchKey(row) || row.batchId}`} direction="row" spacing={1.25} alignItems="flex-start" sx={{ minWidth: 0 }}>
                    <Box aria-hidden sx={{ width: 8, height: 8, borderRadius: '50%', bgcolor: statusTone(row.status) === 'success' ? '#4caf50' : statusTone(row.status) === 'error' ? '#f44336' : statusTone(row.status) === 'warning' ? '#ffc107' : muted, mt: 0.7, flexShrink: 0 }} />
                    <Box sx={{ flex: 1, minWidth: 0 }}>
                      <Typography variant="body2" sx={{ fontWeight: 650, color: text, overflowWrap: 'anywhere' }}>{row.companyName || 'Company name unavailable'}</Typography>
                      <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" alignItems="center">
                        <Chip size="small" color={statusTone(row.status)} variant="outlined" label={row.status} />
                        {submittedCell(row)}
                        {sourceLabel(row.source) ? <Typography variant="caption" sx={{ color: muted }}>{sourceLabel(row.source)}</Typography> : null}
                      </Stack>
                    </Box>
                  </Stack>
                ))}
              </Stack>
            )}
          </Box>
        </Stack>
      </Box>
    </Stack>
  );
};

export default ExpertOverview;
